"logmsg <- function(...) {",
"    z <- paste0(...)",
"    cat(z, \"\\n\")",
"    cat(format(Sys.time(), \"%Y-%m-%d %H:%M:%S\"), \" \", z, \"\\n\", file = LOG, append = TRUE, sep = \"\")",
