"",
"atomic_write_csv <- function(x, path) {",
"    dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)",
"    tmp <- tempfile(pattern = paste0(basename(path), \".\"), tmpdir = dirname(path))",
"    write.csv(x, tmp, row.names = FALSE, na = \"\", fileEncoding = \"UTF-8\")",
"    if (file.exists(path)) ",
"        file.remove(path)",
"    if (!file.rename(tmp, path)) ",
"        stop(\"Atomic CSV rename failed: \", path)",
"    invisible(path)",
"}",
"",
"atomic_saveRDS <- function(x, path) {",
"    dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)",
"    tmp <- tempfile(pattern = paste0(basename(path), \".\"), tmpdir = dirname(path))",
"    saveRDS(x, tmp, compress = FALSE)",
"    if (file.exists(path)) ",
"        file.remove(path)",
"    if (!file.rename(tmp, path)) ",
"        stop(\"Atomic RDS rename failed: \", path)",
"    invisible(path)",
"}",
"",
"read_csv_safe <- function(p) {",
"    if (!file.exists(p)) ",
"        return(data.frame())",
"    tryCatch(read.csv(p, stringsAsFactors = FALSE, check.names = FALSE), error = function(e) data.frame())",
"}",
"",
"read_state <- function() {",
"    z <- read_csv_safe(STATE_FILE)",
"    if (!nrow(z)) ",
"        z <- data.frame(task_id = character(), status = character(), updated = character(), message = character(), result_file = character(), ",
"            stringsAsFactors = FALSE)",
"    z",
"}",
"",
"set_state <- function(task_id, status, message = \"\", result_file = \"\") {",
"    z <- read_state()",
"    k <- match(task_id, z$task_id)",
"    row <- data.frame(task_id = task_id, status = status, updated = as.character(Sys.time()), message = message, result_file = result_file, ",
"        stringsAsFactors = FALSE)",
"    if (is.na(k)) ",
"        z <- rbind(z, row)",
"    else z[k, ] <- row",
"    atomic_write_csv(z, STATE_FILE)",
"    invisible(z)",
"}",
"",
"task_result_path <- function(task_id) file.path(TASK_DIR, paste0(gsub(\"[^A-Za-z0-9_.-]\", \"_\", task_id), \".rds\"))",
"",
"run_task <- function(task_id, fun, force = FALSE) {",
"    CURRENT_RUN_TASKS_V8 <<- unique(c(CURRENT_RUN_TASKS_V8, task_id))",
"    p <- task_result_path(task_id)",
"    st <- read_state()",
"    k <- match(task_id, st$task_id)",
"    if (!force && !is.na(k) && identical(st$status[k], \"DONE\") && file.exists(p)) {",
"        logmsg(\"REUSE completed task: \", task_id)",
"        return(readRDS(p))",
"    }",
"    set_state(task_id, \"RUNNING\", \"task started\", p)",
"    logmsg(\"TASK start: \", task_id)",
"    out <- tryCatch(fun(), interrupt = function(e) {",
"        set_state(task_id, \"INTERRUPTED\", conditionMessage(e), p)",
"        stop(e)",
"    }, error = function(e) e)",
"    if (inherits(out, \"error\")) {",
"        calltxt <- tryCatch(paste(deparse(conditionCall(out)), collapse = \" \"), error = function(e) \"\")",
"        msg <- conditionMessage(out)",
"        if (nzchar(calltxt)) ",
"            msg <- paste0(msg, \" | call: \", calltxt)",
"        set_state(task_id, \"HELD\", msg, p)",
"        writeLines(msg, file.path(OUT, paste0(\"ERROR_\", gsub(\"[^A-Za-z0-9_.-]\", \"_\", task_id), \".txt\")))",
"        logmsg(\"TASK held: \", task_id, \" — \", msg)",
"        return(list(results = data.frame(), holds = data.frame(task_id = task_id, status = \"HELD\", reason = msg, stringsAsFactors = FALSE)))",
"    }",
"    atomic_saveRDS(out, p)",
"    set_state(task_id, \"DONE\", \"completed\", p)",
"    logmsg(\"TASK done: \", task_id)",
"    out",
"}",
"",
"bind_safe <- function(x) {",
"    x <- Filter(function(z) is.data.frame(z) && nrow(z), x)",
"    if (!length(x)) ",
"        return(data.frame())",
"    nms <- unique(unlist(lapply(x, names)))",
"    x <- lapply(x, function(z) {",
"        for (m in setdiff(nms, names(z))) z[[m]] <- NA",
"        z[nms]",
"    })",
"    do.call(rbind, x)",
"}",
