"fast_inventory <- function() {",
"    ff <- character()",
"    for (d in FAST_SOURCE_DIRS) {",
"        rec <- !identical(norm(d), norm(DOWNLOADS))",
"        z <- list.files(d, recursive = rec, full.names = TRUE, include.dirs = FALSE)",
"        if (length(z)) ",
"            ff <- c(ff, z)",
"    }",
"    ff <- unique(ff[file.exists(ff)])",
"    if (!length(ff)) ",
"        return(data.frame(path = character(), basename = character(), bytes = numeric(), extension = character()))",
"    fi <- file.info(ff)",
"    ff <- ff[!is.na(fi$isdir) & !fi$isdir]",
"    data.frame(path = norm(ff), basename = basename(ff), bytes = as.numeric(file.info(ff)$size), extension = tolower(tools::file_ext(ff)), ",
"        stringsAsFactors = FALSE)",
"}",
