"pv_names <- function(d, domain) {",
"    prefix <- switch(domain, reading = \"PV_READ_\", mathematics = \"PV_MATH_\", science = \"PV_SCIE_\", stop(\"Unknown domain: \", ",
"        domain))",
"    grep(paste0(\"^\", prefix), names(d), value = TRUE)",
"}",
"",
"thresholds_for <- function(survey, domain) {",
"    if (survey %in% c(\"PIRLS\", \"TIMSS\")) ",
"        return(c(basic = 475, high = 625))",
"    if (survey == \"PISA\") {",
"        if (domain == \"mathematics\") ",
"            return(c(basic = 420.07, high = 606.99))",
"        if (domain == \"reading\") ",
"            return(c(basic = 407.47, high = 625.61))",
"        if (domain == \"science\") ",
"            return(c(basic = 409.54, high = 633.33))",
"    }",
"    stop(\"No threshold definition for \", survey, \" / \", domain)",
"}",
"",
"weighted_mean <- function(x, w) {",
"    ok <- is.finite(x) & is.finite(w) & w > 0",
"    if (!any(ok)) ",
"        return(NA_real_)",
"    sum(x[ok] * w[ok])/sum(w[ok])",
"}",
"",
"peer_share <- function(unit, peer_member, target_member, w) {",
"    ok <- !is.na(unit) & nzchar(unit) & is.finite(peer_member) & is.finite(target_member) & is.finite(w) & w > 0",
"    if (sum(ok) < 30L) ",
"        return(NA_real_)",
"    u <- as.character(unit)",
"    tw <- ifelse(ok, w, 0)",
"    pw <- ifelse(ok, w * peer_member, 0)",
"    total_w <- ave(tw, u, FUN = sum)",
"    peer_w <- ave(pw, u, FUN = sum)",
"    den <- total_w - ifelse(ok, w, 0)",
"    num <- peer_w - ifelse(ok, w * peer_member, 0)",
"    person_share <- ifelse(ok & den > 0, num/den, NA_real_)",
"    weighted_mean(person_share, w * target_member)",
"}",
"",
"brr_scalar <- function(full, reps, factor) {",
"    if (!is.finite(full) || any(!is.finite(reps))) ",
"        return(NA_real_)",
"    sqrt(factor * sum((reps - full)^2))",
"}",
"",
"pool_pv_stats <- function(full_m, reps_a, factor) {",
"    rc2_pool(full_m, reps_a, factor)",
"}",
"",
"rc2_pool <- function(full, reps, factor) {",
"    full <- as.matrix(full)",
"    if (!nrow(full) || !ncol(full)) ",
"        stop(\"Pooling received an empty estimate matrix\")",
"    if (length(dim(reps)) != 3L || !identical(as.integer(dim(reps)[2:3]), as.integer(dim(full)))) ",
"        stop(\"Pooling replicate dimensions do not match the PV/statistic matrix\")",
"    nm <- colnames(full)",
"    if (is.null(nm)) ",
"        nm <- paste0(\"stat_\", seq_len(ncol(full)))",
"    bad <- is.na(nm) | !nzchar(nm)",
"    nm[bad] <- paste0(\"stat_\", which(bad))",
"    colnames(full) <- make.unique(nm)",
"    rc2_pool_engine_v8(full, reps, factor)",
"}",
"",
"v8_source_names <- function(year) switch(as.character(year), `2015` = c(\"PUF_SPSS_COMBINED_CMB_STU_QQQ.zip\", \"PUF_SAS_COMBINED_CMB_STU_QQQ.zip\", ",
"    \"CY6_MS_CMB_STU_QQQ.sav\", \"CY6_MS_CMB_STU_QQQ.sas7bdat\"), `2018` = c(\"SAS_STU_QQQ.zip\", \"CY07_MSU_STU_QQQ.sas7bdat\", ",
"    \"CY07_MSU_STU_QQQ.sav\"), `2022` = c(\"STU_QQQ_SPSS.zip\", \"CY08MSP_STU_QQQ.sav\"), `2025` = c(\"CY09_MS_STU_PUF.sav\"), character())",
"",
"v8_source_candidates <- function(year, inv) {",
"    want <- v8_source_names(year)",
"    clean <- function(x) tolower(gsub(\" ?\\\\([0-9]+\\\\)(?=\\\\.[^.]+$)\", \"\", basename(x), perl = TRUE))",
"    ix <- match(clean(inv$path), tolower(want))",
"    ok <- !is.na(ix) & file.exists(inv$path)",
"    inv$path[which(ok)[order(ix[ok], inv$path[ok])]]",
"}",
"",
"v8_choose_student_member <- function(members, year) {",
"    bn <- toupper(basename(members))",
"    candidate <- grepl(\"\\\\.(SAV|SAS7BDAT)$\", bn) & grepl(\"STU\", bn) & grepl(\"QQQ|PUF\", bn) & !grepl(\"COG|SCHOOL|TCH\", bn)",
"    cy <- switch(as.character(year), `2015` = \"CY0?6\", `2018` = \"CY0?7\", `2022` = \"CY0?8\", `2025` = \"CY0?9\")",
"    has_cycle <- grepl(\"CY[0-9]+\", bn)",
"    candidate <- candidate & (!has_cycle | grepl(cy, bn))",
"    ix <- which(candidate)",
"    if (!length(ix)) ",
"        stop(\"Geen passend leerlingbestand voor \", year, \" in dit archief\")",
"    pref <- ifelse(grepl(\"\\\\.SAV$\", bn[ix]), 0L, 1L)",
"    ix <- ix[pref == min(pref)]",
"    if (length(ix) != 1L) ",
"        stop(\"Meerdere leerlingbestanden voor \", year, \"; geen automatische keuze: \", paste(members[ix], collapse = \", \"))",
"    members[ix]",
"}",
"",
"v8_pisa_source <- function(year, inv, extract_root) {",
"    candidates <- v8_source_candidates(year, inv)",
"    failures <- character()",
"    for (p in candidates) {",
"        ans <- tryCatch({",
"            if (tolower(tools::file_ext(p)) == \"zip\") {",
"                listing <- unzip(p, list = TRUE)",
"                member <- v8_choose_student_member(listing$Name, year)",
"                if (grepl(\"(^[/\\\\\\\\]|^[A-Za-z]:|(^|[/\\\\\\\\])\\\\.\\\\.([/\\\\\\\\]|$))\", member)) ",
"                  stop(\"Ongeldig archiefpad\")",
"                dest <- file.path(extract_root, paste0(\"wave_\", year), tools::file_path_sans_ext(basename(p)))",
"                dir.create(dest, recursive = TRUE, showWarnings = FALSE)",
"                target <- file.path(dest, member)",
"                expected <- listing$Length[match(member, listing$Name)]",
"                if (!file.exists(target) || !isTRUE(file.info(target)$size == expected)) ",
"                  unzip(p, files = member, exdir = dest)",
"                if (!file.exists(target) || !isTRUE(file.info(target)$size == expected)) ",
"                  stop(\"Onvolledig uitgepakt leerlingbestand\")",
"            }",
"            else target <- p",
"            logmsg(\"PISA \", year, \" bron: \", target)",
"            list(path = norm(target), control = \"\", source_archive = p, year = year)",
"        }, error = function(e) e)",
"        if (!inherits(ans, \"error\")) ",
"            return(ans)",
"        failures <- c(failures, paste(basename(p), conditionMessage(ans), sep = \": \"))",
"    }",
"    fallback <- tryCatch(rc2_pisa_source(year, inv, extract_root), error = function(e) e)",
"    if (!inherits(fallback, \"error\")) ",
"        return(fallback)",
"    stop(\"PISA \", year, \": geen leesbare bron. Verwacht in Downloads: \", paste(v8_source_names(year), collapse = \" OF \"), ",
"        if (length(failures)) ",
"            paste0(\". Details: \", paste(failures, collapse = \"; \"))",
"        else \"\", \". Engine: \", conditionMessage(fallback))",
"}",
"",
"v8_quantile_codes <- function(AE, x, W, P = NULL) {",
"    W <- as.matrix(W)",
"    if (length(x) != nrow(W) || !all(is.finite(W)) || any(W < 0)) ",
"        stop(\"Invalid Cobreros weight matrix or row alignment\")",
"    ok <- is.finite(x)",
"    if (!is.null(P)) {",
"        P <- as.matrix(P)",
"        if (nrow(P) != length(x) || ncol(P) != 10L) ",
"            stop(\"Expected 10 aligned plausible values\")",
"        ok <- ok & rowSums(is.finite(P)) == ncol(P)",
"    }",
"    if (sum(ok) < 100L || any(colSums(W[ok, , drop = FALSE]) <= 0)) ",
"        stop(\"Insufficient valid SES/PV observations or replicate weight support\")",
"    ans <- matrix(NA_integer_, nrow(W), ncol(W))",
"    ans[ok, ] <- AE$quantile_codes(x[ok], W[ok, , drop = FALSE], k = 4, mode = \"replicate\", seed = 7)",
"    attr(ans, \"included\") <- ok",
"    ans",
"}",
"",
"normalize_canonical_meta <- function(x, survey, year) {",
"    if (is.null(x$meta) || !is.list(x$meta)) ",
"        x$meta <- list()",
"    if (is.null(x$meta$survey) || !length(x$meta$survey) || !nzchar(as.character(x$meta$survey)[1])) ",
"        x$meta$survey <- survey",
"    if (is.null(x$meta$year) || !length(x$meta$year) || !is.finite(suppressWarnings(as.numeric(x$meta$year)[1]))) ",
"        x$meta$year <- as.integer(year)",
"    x",
"}",
"",
"language_groups <- function(obj) {",
"    d <- obj$data",
"    g <- d$DEMO_LANGUAGE",
"    if (is.null(g)) ",
"        return(list(ok = FALSE, reason = \"DEMO_LANGUAGE ontbreekt\"))",
"    cats <- sort(unique(as.character(g[!is.na(g)])))",
"    if (obj$meta$survey == \"PISA\" && all(c(\"same\", \"other\") %in% cats)) {",
"        tl <- if (\"TEST_LANGUAGE\" %in% names(d)) ",
"            d$TEST_LANGUAGE",
"        else rep(NA, nrow(d))",
"        tl2 <- tolower(trimws(as.character(tl)))",
"        non_dutch_test <- !is.na(tl2) & nzchar(tl2) & !grepl(\"(^nld$|dutch|nederlands)\", tl2)",
"        if (any(non_dutch_test)) ",
"            return(list(ok = FALSE, reason = \"PISA bevat niet-Nederlandse toetstaal; same/other niet exact NL/non-NL.\"))",
"        grp <- ifelse(g == \"same\", \"test_language_home\", ifelse(g == \"other\", \"other_language_home\", NA_character_))",
"        return(list(ok = TRUE, group = grp, reference = \"test_language_home\", contrast = \"other_language_home\", definition = \"same as Dutch assessment language versus other language\"))",
"    }",
"    list(ok = FALSE, reason = paste0(\"IEA construct is niet exact binaire taalidentiteit; categorieën: \", paste(cats, collapse = \";\")))",
"}",
"",
"migration_groups <- function(obj) {",
"    d <- obj$data",
"    g <- d$DEMO_MIGRATION",
"    if (is.null(g)) ",
"        return(list(ok = FALSE, reason = \"DEMO_MIGRATION ontbreekt\"))",
"    cats <- sort(unique(as.character(g[!is.na(g)])))",
"    valid <- intersect(c(\"native\", \"first_generation\", \"second_generation\", \"third_generation\"), cats)",
"    if (!all(c(\"native\", \"first_generation\", \"second_generation\") %in% valid)) ",
"        return(list(ok = FALSE, reason = paste0(\"Geen volledig native/first/second construct; categorieën: \", paste(cats, ",
"            collapse = \";\"))))",
"    list(ok = TRUE, group = as.character(g), groups = valid, definition = \"source-labelled migration generation; third only when explicitly identified\")",
"}",
"",
"iea_ses_wave <- function(obj, domains) {",
"    survey <- obj$meta$survey",
"    year <- as.integer(obj$meta$year)",
"    d <- obj$data",
"    des <- rc2_replicate_design(d, survey, year)",
"    out <- list()",
"    for (domain in domains) {",
"        pp <- pv_names(d, domain)",
"        if (!length(pp)) ",
"            next",
"        th <- thresholds_for(survey, domain)",
"        stat_one <- function(w) {",
"            tails <- rc2_tails_rank(d$SES, w)",
"            z <- matrix(NA_real_, nrow = length(pp), ncol = 7)",
"            colnames(z) <- c(\"q1_mean\", \"q4_mean\", \"q1_basic\", \"q4_basic\", \"q1_high\", \"q4_high\", \"total_high\")",
"            for (m in seq_along(pp)) {",
"                y <- rc2_num(d[[pp[m]]])",
"                basic <- ifelse(is.finite(y), as.numeric(y >= th[\"basic\"]), NA_real_)",
"                high <- ifelse(is.finite(y), as.numeric(y >= th[\"high\"]), NA_real_)",
"                z[m, ] <- c(rc2_weighted_mean(y, w * tails$q1), rc2_weighted_mean(y, w * tails$q4), rc2_weighted_mean(basic, ",
"                  w * tails$q1), rc2_weighted_mean(basic, w * tails$q4), rc2_weighted_mean(high, w * tails$q1), rc2_weighted_mean(high, ",
"                  w * tails$q4), rc2_weighted_mean(high, w))",
"            }",
"            z",
"        }",
"        full <- stat_one(des$w)",
"        R <- des$n",
"        reps <- array(NA_real_, dim = c(R, nrow(full), ncol(full)))",
"        for (r in seq_len(R)) reps[r, , ] <- stat_one(rc2_repweight(des, r))",
"        p <- rc2_pool(full, reps, des$factor)",
"        est <- as.numeric(p$estimate)",
"        se <- as.numeric(p$se)",
"        nms <- colnames(full)",
"        q <- data.frame(survey = survey, year = year, domain = domain, statistic = nms, estimate = est, se = se, ci_low = est - ",
"            1.96 * se, ci_high = est + 1.96 * se, ses_definition = if (survey == \"PIRLS\") ",
"            \"books_at_home_5cat_fractional_quartiles\"",
"        else \"student_books_5cat_fractional_quartiles\", stringsAsFactors = FALSE)",
"        q$unit <- ifelse(grepl(\"basic|high\", q$statistic), \"proportion\", \"score_points\")",
"        gap_one <- function(w) {",
"            tails <- rc2_tails_rank(d$SES, w)",
"            z <- matrix(NA_real_, nrow = length(pp), ncol = 3)",
"            colnames(z) <- c(\"score_gap_q4_minus_q1\", \"basic_gap_q4_minus_q1\", \"high_gap_q4_minus_q1\")",
"            for (m in seq_along(pp)) {",
"                y <- rc2_num(d[[pp[m]]])",
"                basic <- ifelse(is.finite(y), as.numeric(y >= th[\"basic\"]), NA_real_)",
"                high <- ifelse(is.finite(y), as.numeric(y >= th[\"high\"]), NA_real_)",
"                z[m, ] <- c(rc2_weighted_mean(y, w * tails$q4) - rc2_weighted_mean(y, w * tails$q1), rc2_weighted_mean(basic, ",
"                  w * tails$q4) - rc2_weighted_mean(basic, w * tails$q1), rc2_weighted_mean(high, w * tails$q4) - rc2_weighted_mean(high, ",
"                  w * tails$q1))",
"            }",
"            z",
"        }",
"        gf <- gap_one(des$w)",
"        gr <- array(NA_real_, dim = c(R, nrow(gf), ncol(gf)))",
"        for (r in seq_len(R)) gr[r, , ] <- gap_one(rc2_repweight(des, r))",
"        gp <- rc2_pool(gf, gr, des$factor)",
"        g <- data.frame(survey = survey, year = year, domain = domain, statistic = colnames(gf), estimate = as.numeric(gp$estimate), ",
"            se = as.numeric(gp$se), stringsAsFactors = FALSE)",
"        g$ci_low <- g$estimate - 1.96 * g$se",
"        g$ci_high <- g$estimate + 1.96 * g$se",
"        g$ses_definition <- q$ses_definition[1]",
"        g$unit <- ifelse(grepl(\"basic|high\", g$statistic), \"proportion_difference\", \"score_points\")",
"        out[[length(out) + 1L]] <- rbind(q, g)",
"    }",
"    bind_safe(out)",
"}",
"",
"pool_group_means <- function(obj, domain, groups) {",
"    d <- obj$data",
"    pp <- pv_names(d, domain)",
"    if (!length(pp)) ",
"        return(NULL)",
"    des <- rc2_replicate_design(d, obj$meta$survey, obj$meta$year)",
"    stat_one <- function(w) {",
"        z <- matrix(NA_real_, nrow = length(pp), ncol = length(groups))",
"        colnames(z) <- names(groups)",
"        for (m in seq_along(pp)) {",
"            y <- rc2_num(d[[pp[m]]])",
"            for (k in seq_along(groups)) z[m, k] <- rc2_weighted_mean(y, w * as.numeric(groups[[k]]))",
"        }",
"        z",
"    }",
"    full <- stat_one(des$w)",
"    reps <- array(NA_real_, dim = c(des$n, nrow(full), ncol(full)))",
"    for (r in seq_len(des$n)) reps[r, , ] <- stat_one(rc2_repweight(des, r))",
"    p <- rc2_pool(full, reps, des$factor)",
"    list(est = as.numeric(p$estimate), se = as.numeric(p$se), names = colnames(full))",
"}",
"",
"demographic_wave <- function(obj, domains) {",
"    survey <- obj$meta$survey",
"    year <- as.integer(obj$meta$year)",
"    rows <- list()",
"    holds <- list()",
"    L <- language_groups(obj)",
"    M <- migration_groups(obj)",
"    for (domain in domains) {",
"        if (isTRUE(L$ok)) {",
"            lev <- pool_group_means(obj, domain, list(test_language_home = L$group == \"test_language_home\", other_language_home = L$group == ",
"                \"other_language_home\"))",
"            if (!is.null(lev)) {",
"                for (i in seq_along(lev$est)) rows[[length(rows) + 1L]] <- data.frame(survey = survey, year = year, domain = domain, ",
"                  family = \"home_language\", group = lev$names[i], statistic = \"mean_score\", estimate = lev$est[i], se = lev$se[i], ",
"                  ci_low = lev$est[i] - 1.96 * lev$se[i], ci_high = lev$est[i] + 1.96 * lev$se[i], definition = L$definition, ",
"                  stringsAsFactors = FALSE)",
"                d <- obj$data",
"                des <- rc2_replicate_design(d, survey, year)",
"                pp <- pv_names(d, domain)",
"                one <- function(w) {",
"                  vapply(pp, function(pv) {",
"                    y <- rc2_num(d[[pv]])",
"                    rc2_weighted_mean(y, w * (L$group == \"other_language_home\")) - rc2_weighted_mean(y, w * (L$group == \"test_language_home\"))",
"                  }, numeric(1))",
"                }",
"                f <- matrix(one(des$w), ncol = 1, dimnames = list(NULL, \"mean_score_gap\"))",
"                rr <- array(NA_real_, c(des$n, nrow(f), 1L))",
"                for (r in seq_len(des$n)) rr[r, , 1] <- one(rc2_repweight(des, r))",
"                po <- rc2_pool(f, rr, des$factor)",
"                rows[[length(rows) + 1L]] <- data.frame(survey = survey, year = year, domain = domain, family = \"home_language\", ",
"                  group = \"other_minus_test_language_home\", statistic = \"mean_score_gap\", estimate = as.numeric(po$estimate[1]), ",
"                  se = as.numeric(po$se[1]), ci_low = as.numeric(po$estimate[1] - 1.96 * po$se[1]), ci_high = as.numeric(po$estimate[1] + ",
"                    1.96 * po$se[1]), definition = L$definition, stringsAsFactors = FALSE)",
"            }",
"        }",
"        else holds[[length(holds) + 1L]] <- data.frame(survey = survey, year = year, domain = domain, family = \"home_language\", ",
"            status = \"UNAVAILABLE\", reason = L$reason, stringsAsFactors = FALSE)",
"        if (isTRUE(M$ok)) {",
"            gs <- M$groups",
"            gl <- setNames(lapply(gs, function(z) M$group == z), gs)",
"            lev <- pool_group_means(obj, domain, gl)",
"            if (!is.null(lev)) {",
"                for (i in seq_along(lev$est)) rows[[length(rows) + 1L]] <- data.frame(survey = survey, year = year, domain = domain, ",
"                  family = \"migration_generation\", group = lev$names[i], statistic = \"mean_score\", estimate = lev$est[i], ",
"                  se = lev$se[i], ci_low = lev$est[i] - 1.96 * lev$se[i], ci_high = lev$est[i] + 1.96 * lev$se[i], definition = M$definition, ",
"                  stringsAsFactors = FALSE)",
"                d <- obj$data",
"                des <- rc2_replicate_design(d, survey, year)",
"                pp <- pv_names(d, domain)",
"                for (g in setdiff(gs, \"native\")) {",
"                  one <- function(w) vapply(pp, function(pv) {",
"                    y <- rc2_num(d[[pv]])",
"                    rc2_weighted_mean(y, w * (M$group == g)) - rc2_weighted_mean(y, w * (M$group == \"native\"))",
"                  }, numeric(1))",
"                  f <- matrix(one(des$w), ncol = 1, dimnames = list(NULL, \"mean_score_gap\"))",
"                  rr <- array(NA_real_, c(des$n, nrow(f), 1L))",
"                  for (r in seq_len(des$n)) rr[r, , 1] <- one(rc2_repweight(des, r))",
"                  po <- rc2_pool(f, rr, des$factor)",
"                  rows[[length(rows) + 1L]] <- data.frame(survey = survey, year = year, domain = domain, family = \"migration_generation\", ",
"                    group = paste0(g, \"_minus_native\"), statistic = \"mean_score_gap\", estimate = as.numeric(po$estimate[1]), ",
"                    se = as.numeric(po$se[1]), ci_low = as.numeric(po$estimate[1] - 1.96 * po$se[1]), ci_high = as.numeric(po$estimate[1] + ",
"                      1.96 * po$se[1]), definition = M$definition, stringsAsFactors = FALSE)",
"                }",
"            }",
"        }",
"        else holds[[length(holds) + 1L]] <- data.frame(survey = survey, year = year, domain = domain, family = \"migration_generation\", ",
"            status = \"UNAVAILABLE\", reason = M$reason, stringsAsFactors = FALSE)",
"    }",
"    list(results = bind_safe(rows), holds = bind_safe(holds))",
"}",
"",
"unit_for <- function(obj, peer_definition) {",
"    d <- obj$data",
"    survey <- obj$meta$survey",
"    if (peer_definition == \"whole_school\") ",
"        return(as.character(d$SCHOOL))",
"    if (survey %in% c(\"PIRLS\", \"TIMSS\")) {",
"        sc <- as.character(d$SCHOOL)",
"        cl <- as.character(d$CLASS)",
"        ok <- !is.na(sc) & nzchar(sc) & !is.na(cl) & nzchar(cl)",
"        u <- rep(NA_character_, length(sc))",
"        u[ok] <- paste(sc[ok], cl[ok], sep = \"::CLASS::\")",
"        return(u)",
"    }",
"    prog <- if (\"PROGRAM\" %in% names(d)) ",
"        as.character(d$PROGRAM)",
"    else rep(NA_character_, nrow(d))",
"    ok <- !is.na(d$SCHOOL) & nzchar(as.character(d$SCHOOL)) & !is.na(prog) & nzchar(prog)",
"    u <- rep(NA_character_, nrow(d))",
"    u[ok] <- paste(d$SCHOOL[ok], prog[ok], sep = \"::PROGN::\")",
"    u",
"}",
"",
"peer_by_weight_matrix <- function(unit, peer_member, target_member, W) {",
"    ok <- !is.na(unit) & nzchar(unit) & is.finite(peer_member) & is.finite(target_member)",
"    gid <- match(as.character(unit), unique(as.character(unit[ok])))",
"    valid <- ok & !is.na(gid)",
"    ans <- rep(NA_real_, ncol(W))",
"    if (sum(valid) < 30L) ",
"        return(ans)",
"    gv <- gid[valid]",
"    Wv <- W[valid, , drop = FALSE]",
"    p <- peer_member[valid]",
"    t <- target_member[valid]",
"    total <- rowsum(Wv, gv, reorder = FALSE)",
"    numer <- rowsum(Wv * p, gv, reorder = FALSE)",
"    den_i <- total[gv, , drop = FALSE] - Wv",
"    num_i <- numer[gv, , drop = FALSE] - Wv * p",
"    share <- num_i/den_i",
"    share[!is.finite(share)] <- NA_real_",
"    TW <- Wv * t",
"    den <- colSums(TW, na.rm = TRUE)",
"    num <- colSums(TW * share, na.rm = TRUE)",
"    ans[den > 0] <- 100 * num[den > 0]/den[den > 0]",
"    ans",
"}",
"",
"binary_peer_rep <- function(obj, unit, group, positive, target) {",
"    d <- obj$data",
"    des <- rc2_replicate_design(d, obj$meta$survey, obj$meta$year)",
"    W <- cbind(des$w, vapply(seq_len(des$n), function(r) rc2_repweight(des, r), numeric(nrow(d))))",
"    peer <- as.numeric(!is.na(group) & group == positive)",
"    tar <- as.numeric(!is.na(group) & group == target)",
"    e <- peer_by_weight_matrix(unit, peer, tar, W)",
"    full <- e[1]",
"    reps <- e[-1]",
"    se <- brr_scalar(full, reps, des$factor)",
"    c(estimate = full, se = se, ci_low = full - 1.96 * se, ci_high = full + 1.96 * se)",
"}",
"",
"ses_peer_rep_iea <- function(obj, unit) {",
"    d <- obj$data",
"    des <- rc2_replicate_design(d, obj$meta$survey, obj$meta$year)",
"    one <- function(w) {",
"        t <- rc2_tails_rank(d$SES, w)",
"        c(q1_target_pct_q4_peers = 100 * peer_share(unit, t$q4, t$q1, w), q4_target_pct_q1_peers = 100 * peer_share(unit, ",
"            t$q1, t$q4, w))",
"    }",
"    full <- one(des$w)",
"    reps <- vapply(seq_len(des$n), function(r) one(rc2_repweight(des, r)), numeric(length(full)))",
"    se <- vapply(seq_along(full), function(k) brr_scalar(full[k], reps[k, ], des$factor), numeric(1))",
"    data.frame(statistic = names(full), estimate = full, se = se, ci_low = full - 1.96 * se, ci_high = full + 1.96 * se, ",
"        stringsAsFactors = FALSE)",
"}",
"",
"high_peer_pv <- function(obj, domain, unit) {",
"    d <- obj$data",
"    pp <- pv_names(d, domain)",
"    if (!length(pp)) ",
"        return(data.frame())",
"    th <- thresholds_for(obj$meta$survey, domain)[\"high\"]",
"    des <- rc2_replicate_design(d, obj$meta$survey, obj$meta$year)",
"    W <- cbind(des$w, vapply(seq_len(des$n), function(r) rc2_repweight(des, r), numeric(nrow(d))))",
"    M <- length(pp)",
"    R <- des$n",
"    final <- matrix(NA_real_, M, 2)",
"    colnames(final) <- c(\"self_below_high\", \"self_high\")",
"    reps <- array(NA_real_, c(R, M, 2))",
"    for (m in seq_along(pp)) {",
"        y <- rc2_num(d[[pp[m]]])",
"        hi <- as.numeric(is.finite(y) & y >= th)",
"        lo <- as.numeric(is.finite(y) & y < th)",
"        e1 <- peer_by_weight_matrix(unit, hi, lo, W)",
"        e2 <- peer_by_weight_matrix(unit, hi, hi, W)",
"        final[m, ] <- c(e1[1], e2[1])",
"        reps[, m, 1] <- e1[-1]",
"        reps[, m, 2] <- e2[-1]",
"    }",
"    p <- rc2_pool(final, reps, des$factor)",
"    data.frame(statistic = colnames(final), estimate = as.numeric(p$estimate), se = as.numeric(p$se), ci_low = as.numeric(p$estimate) - ",
"        1.96 * as.numeric(p$se), ci_high = as.numeric(p$estimate) + 1.96 * as.numeric(p$se), threshold = as.numeric(th), ",
"        stringsAsFactors = FALSE)",
"}",
"",
"peer_wave <- function(obj, domains, include_ses_iea = TRUE) {",
"    survey <- obj$meta$survey",
"    year <- as.integer(obj$meta$year)",
"    rows <- list()",
"    holds <- list()",
"    L <- language_groups(obj)",
"    M <- migration_groups(obj)",
"    for (pd in c(\"direct_learning_environment\", \"whole_school\")) {",
"        unit <- unit_for(obj, pd)",
"        if (!any(!is.na(unit) & nzchar(unit))) {",
"            holds[[length(holds) + 1L]] <- data.frame(survey = survey, year = year, family = \"peer\", peer_definition = pd, ",
"                status = \"UNAVAILABLE\", reason = \"Geen geldige peer-unit.\", stringsAsFactors = FALSE)",
"            next",
"        }",
"        if (include_ses_iea && survey %in% c(\"PIRLS\", \"TIMSS\")) {",
"            z <- ses_peer_rep_iea(obj, unit)",
"            if (nrow(z)) {",
"                z$survey <- survey",
"                z$year <- year",
"                z$family <- \"ses_peer_exposure\"",
"                z$peer_definition <- pd",
"                rows[[length(rows) + 1L]] <- z",
"            }",
"        }",
"        if (isTRUE(L$ok)) {",
"            z <- binary_peer_rep(obj, unit, L$group, \"test_language_home\", \"other_language_home\")",
"            rows[[length(rows) + 1L]] <- data.frame(survey = survey, year = year, domain = \"\", family = \"home_language_peer_exposure\", ",
"                peer_definition = pd, statistic = \"other_language_target_pct_test_language_home_peers\", estimate = z[\"estimate\"], ",
"                se = z[\"se\"], ci_low = z[\"ci_low\"], ci_high = z[\"ci_high\"], stringsAsFactors = FALSE)",
"        }",
"        if (isTRUE(M$ok)) {",
"            for (g in setdiff(M$groups, \"native\")) {",
"                z <- binary_peer_rep(obj, unit, M$group, \"native\", g)",
"                rows[[length(rows) + 1L]] <- data.frame(survey = survey, year = year, domain = \"\", family = \"migration_peer_exposure\", ",
"                  peer_definition = pd, statistic = paste0(g, \"_target_pct_native_peers\"), estimate = z[\"estimate\"], se = z[\"se\"], ",
"                  ci_low = z[\"ci_low\"], ci_high = z[\"ci_high\"], stringsAsFactors = FALSE)",
"            }",
"        }",
"        for (domain in domains) {",
"            z <- high_peer_pv(obj, domain, unit)",
"            if (nrow(z)) {",
"                z$survey <- survey",
"                z$year <- year",
"                z$domain <- domain",
"                z$family <- \"high_proficiency_peer_exposure\"",
"                z$peer_definition <- pd",
"                rows[[length(rows) + 1L]] <- z",
"            }",
"        }",
"    }",
"    list(results = bind_safe(rows), holds = bind_safe(holds))",
"}",
"",
"ensure_packages <- function(pkgs) {",
"    miss <- pkgs[!vapply(pkgs, requireNamespace, logical(1), quietly = TRUE)]",
"    if (length(miss)) {",
"        logmsg(\"Installing missing packages: \", paste(miss, collapse = \", \"))",
"        old_timeout <- getOption(\"timeout\", 60)",
"        options(timeout = max(1200, old_timeout))",
"        on.exit(options(timeout = old_timeout), add = TRUE)",
"        for (pkg in miss) {",
"            args <- list(pkg, repos = \"https://cloud.r-project.org\")",
"            if (.Platform$OS.type == \"windows\") ",
"                args$type <- \"binary\"",
"            tryCatch(do.call(install.packages, args), error = function(e) stop(\"Installatie package \", pkg, \" faalde: \", ",
"                conditionMessage(e)))",
"            if (!requireNamespace(pkg, quietly = TRUE)) ",
"                stop(\"Package \", pkg, \" ontbreekt na installatiepoging\")",
"        }",
"    }",
"}",
"",
"ensure_cobreros_repo <- function() {",
"    repo <- file.path(DOWNLOADS, \"pisa_2025_cobreros\")",
"    git <- Sys.which(\"git\")",
"    if (!nzchar(git)) ",
"        stop(\"Git ontbreekt. Installeer Git for Windows, herstart RStudio, en controleer git --version + git lfs version.\")",
"    if (dir.exists(repo) && !dir.exists(file.path(repo, \".git\"))) ",
"        stop(\"Map bestaat maar is geen git repository: \", repo)",
"    if (!dir.exists(repo)) {",
"        if (!AUTO_PREPARE_COBREROS_REPO) ",
"            stop(\"Cobreros repo ontbreekt: \", repo)",
"        old <- Sys.getenv(\"GIT_LFS_SKIP_SMUDGE\", unset = NA)",
"        Sys.setenv(GIT_LFS_SKIP_SMUDGE = \"1\")",
"        on.exit(if (is.na(old)) Sys.unsetenv(\"GIT_LFS_SKIP_SMUDGE\") else Sys.setenv(GIT_LFS_SKIP_SMUDGE = old), add = TRUE)",
"        st <- system2(git, c(\"clone\", \"--no-checkout\", COBREROS_REPO_URL, repo))",
"        if (st != 0) ",
"            stop(\"git clone Cobreros faalde\")",
"    }",
"    st <- system2(git, c(\"-C\", repo, \"fetch\", \"origin\", COBREROS_PIN, \"--depth\", \"1\"))",
"    if (st != 0) ",
"        stop(\"git fetch pinned Cobreros commit faalde\")",
"    st <- system2(git, c(\"-C\", repo, \"checkout\", \"--force\", \"--detach\", COBREROS_PIN))",
"    if (st != 0) ",
"        stop(\"checkout pinned Cobreros commit faalde\")",
"    need <- c(sprintf(\"data/extract/stu_%s.parquet\", c(2015, 2018, 2022, 2025)), sprintf(\"data/extract/wts_%s.npy\", c(2015, ",
"        2018, 2022, 2025)))",
"    system2(git, c(\"-C\", repo, \"lfs\", \"install\", \"--local\"), stdout = FALSE, stderr = FALSE)",
"    inc <- paste(need, collapse = \",\")",
"    is_pointer <- function(p) !file.exists(p) || is.na(file.info(p)$size) || file.info(p)$size < 10000L",
"    if (any(vapply(file.path(repo, need), is_pointer, logical(1)))) {",
"        logmsg(\"Git LFS: fetching only 8 required Cobreros inputs\")",
"        st <- system2(git, c(\"-C\", repo, \"lfs\", \"fetch\", \"origin\", COBREROS_PIN, paste0(\"--include=\", inc), \"--exclude=\"))",
"        if (st != 0) ",
"            logmsg(\"git lfs fetch returned status \", st, \"; trying pull fallback\")",
"        st2 <- system2(git, c(\"-C\", repo, \"lfs\", \"pull\", \"origin\", COBREROS_PIN, paste0(\"--include=\", inc), \"--exclude=\"))",
"        if (st2 != 0 && st != 0) ",
"            stop(\"git lfs fetch/pull voor benodigde PISA-extracten faalde\")",
"        system2(git, c(\"-C\", repo, \"lfs\", \"checkout\"), stdout = FALSE, stderr = FALSE)",
"    }",
"    miss <- file.path(repo, need)[vapply(file.path(repo, need), is_pointer, logical(1))]",
"    if (length(miss)) ",
"        stop(\"Cobreros LFS inputs ontbreken na fetch/pull: \", paste(basename(miss), collapse = \", \"))",
"    repo",
"}",
"",
"author_summarise_matrix <- function(final_m, reps_a, factor = 1/(80 * 0.25)) {",
"    M <- nrow(final_m)",
"    K <- ncol(final_m)",
"    R <- dim(reps_a)[1]",
"    mu <- colMeans(final_m)",
"    V <- matrix(0, K, K)",
"    for (m in seq_len(M)) {",
"        delta <- t(reps_a[, m, , drop = FALSE][, 1, ]) - matrix(final_m[m, ], nrow = K, ncol = R)",
"        V <- V + tcrossprod(delta) * factor/M",
"    }",
"    if (M > 1) ",
"        V <- V + (1 + 1/M) * stats::cov(final_m)",
"    list(estimate = mu, covariance = V, se = sqrt(pmax(0, diag(V))))",
"}",
"",
"language_groups <- function(obj) {",
"    g <- obj$data$DEMO_LANGUAGE",
"    if (is.null(g)) ",
"        return(list(ok = FALSE, reason = \"DEMO_LANGUAGE ontbreekt\"))",
"    cats <- sort(unique(as.character(g[!is.na(g)])))",
"    if (obj$meta$survey == \"PISA\" && all(c(\"same\", \"other\") %in% cats)) {",
"        group <- ifelse(g == \"same\", \"test_language_home\", ifelse(g == \"other\", \"other_language_home\", NA_character_))",
"        return(list(ok = TRUE, group = group, reference = \"test_language_home\", contrast = \"other_language_home\", definition = \"same_as_assessment_language_vs_other\"))",
"    }",
"    list(ok = FALSE, reason = paste0(\"Bronconstruct niet exact same/other toetstaal; categorieën: \", paste(cats, collapse = \";\")))",
"}",
"",
"v9_validation_ok <- function(x) {",
"    is.data.frame(x) && nrow(x) == 4L && all(c(\"year\", \"abs_diff\") %in% names(x)) && setequal(x$year, c(2015L, 2018L, 2022L, ",
"        2025L)) && all(is.finite(x$abs_diff)) && max(x$abs_diff) <= 0.35",
"}",
"",
"v9_choose_countries <- function(mode, available, custom = NULL) {",
"    fixed <- v9_codes(COMMON42)",
"    available <- v9_codes(available)",
"    if (!is.null(custom)) ",
"        return(v9_codes(custom))",
"    switch(as.character(mode), `1` = \"NLD\", `2` = c(\"NLD\", setdiff(fixed, \"NLD\")), `3` = setdiff(sort(available), fixed), ",
"        `4` = c(\"NLD\", setdiff(sort(unique(c(fixed, available))), \"NLD\")), stop(\"Invalid country selection\"))",
"}",
"",
"canonical_ok <- function(x, survey, year, need = character()) {",
"    if (!is.list(x) || !is.data.frame(x$data) || !nrow(x$data)) ",
"        return(FALSE)",
"    x <- normalize_canonical_meta(x, survey, year)",
"    if (!identical(as.character(x$meta$survey)[1], survey) || as.integer(x$meta$year)[1] != as.integer(year)) ",
"        return(FALSE)",
"    cc <- x$meta$v9_country",
"    if (is.null(cc)) ",
"        cc <- x$meta$country",
"    if (!is.null(cc) && length(cc) && !identical(v9_codes(cc), ACTIVE_COUNTRY)) ",
"        return(FALSE)",
"    all(need %in% names(x$data))",
"}",
"",
"find_canonical <- function(survey, year, need) {",
"    p <- file.path(CACHE, sprintf(\"canonical_%s_%s_%s.rds\", survey, year, ACTIVE_COUNTRY))",
"    if (file.exists(p)) {",
"        x <- tryCatch(readRDS(p), error = function(e) NULL)",
"        if (canonical_ok(x, survey, year, need) && identical(x$meta$v9_country, ACTIVE_COUNTRY)) ",
"            return(x)",
"        if (is.list(x) && !is.null(x$meta$v9_country) && !identical(x$meta$v9_country, ACTIVE_COUNTRY)) ",
"            stop(\"Wrong-country canonical cache retained for review: \", p)",
"    }",
"    ccpat <- paste0(\"(^|_)\", ACTIVE_COUNTRY, \"(_|\\\\.|$)\")",
"    candidates <- RDS_FILES[grepl(ccpat, basename(RDS_FILES), ignore.case = TRUE)]",
"    candidates <- candidates[grepl(survey, basename(candidates), ignore.case = TRUE) & grepl(as.character(year), basename(candidates), ",
"        fixed = TRUE)]",
"    bad <- survey == \"PIRLS\" && year %in% c(2001L, 2006L) || survey == \"TIMSS\" && year %in% c(2003L, 2007L, 2015L)",
"    if (bad) ",
"        candidates <- candidates[!grepl(\"23_slide_only_completion|20_rc2_domains\", candidates)]",
"    if (length(candidates)) ",
"        candidates <- candidates[order(file.info(candidates)$mtime, decreasing = TRUE)]",
"    for (q in candidates) {",
"        x <- tryCatch(readRDS(q), error = function(e) NULL)",
"        if (canonical_ok(x, survey, year, need)) {",
"            x <- normalize_canonical_meta(x, survey, year)",
"            save_canonical(x, survey, year)",
"            logmsg(\"REUSE canonical \", ACTIVE_COUNTRY, \" \", survey, \" \", year, \" <- \", q)",
"            return(x)",
"        }",
"    }",
"    NULL",
"}",
"",
"save_canonical <- function(obj, survey, year) {",
"    obj <- normalize_canonical_meta(obj, survey, year)",
"    obj$meta$v9_country <- ACTIVE_COUNTRY",
"    obj$meta$v9_schema <- V9_SCHEMA",
"    p <- file.path(CACHE, sprintf(\"canonical_%s_%s_%s.rds\", survey, year, ACTIVE_COUNTRY))",
"    atomic_saveRDS(obj, p)",
"    invisible(p)",
"}",
"",
"v9_timss_sources <- function(year, ...) {",
"    key <- as.character(year)",
"    if (exists(key, envir = V9_PISA_WAVE_ERRORS, inherits = FALSE)) ",
"        stop(get(key, envir = V9_PISA_WAVE_ERRORS))",
"    if (!exists(key, envir = V9_TIMSS_SOURCE_CACHE, inherits = FALSE)) ",
"        assign(key, rc2_timss_sources(year, ...), envir = V9_TIMSS_SOURCE_CACHE)",
"    get(key, envir = V9_TIMSS_SOURCE_CACHE, inherits = FALSE)",
"}",
"",
"v9_prepare_pisa_wave <- function(year, targets = COUNTRIES) {",
"    original <- ACTIVE_COUNTRY",
"    on.exit(ACTIVE_COUNTRY <<- original, add = TRUE)",
"    src <- v8_pisa_source(year, INV, file.path(CACHE, \"pisa_extracts\"))",
"    pattern <- paste0(\"^(CNT|COUNTRY|CNTSCHID|SCHOOLID|SCHOOL_ID|CNTSTUID|STIDSTD|STUDENTID|STUDENT_ID|\", \"ISCEDL|ISCEDP|PROGN|ESCS|W_FSTUWT|W_FSTR[0-9]+|W_FSTURWT[0-9]+|\", ",
"        \"IMMIG|ST019Q01T|ST019Q02T|ST019Q03T|ST019Q01TA|ST019Q02TA|ST019Q03TA|ST004D01T|ST004D01TA|ST022Q01TA|LANGTEST_COG|LANGTEST_QQQ|LANGTEST|LANGN|STLANG|\", \"PV[0-9]+MATH|PV[0-9]+SCIE|PV[0-9]+READ)$\")",
"    logmsg(\"ONE shared minimal-column PISA import: \", year)",
"    raw <- if (nzchar(src$control)) ",
"        rc2_fwf(src$path, src$control, pattern)",
"    else {",
"        h <- rc2_header(src$path)",
"        rc2_read_selected(src$path, h$variable[grepl(pattern, h$upper) | h$variable %in% rc2_demo_candidates(h)])",
"    }",
"    raw <- as.data.frame(lapply(raw, rc2_clean_labeled), stringsAsFactors = FALSE)",
"    cv <- rc2_choose(names(raw), c(\"CNT\", \"COUNTRY\"))",
"    if (is.na(cv) || !nzchar(cv)) ",
"        stop(\"PISA country field unavailable: \", year)",
"    codes <- toupper(rc2_chr(raw[[cv]]))",
"    present <- v9_codes(unique(codes))",
"    assign(as.character(year), setdiff(targets, present), envir = V9_PISA_ABSENT)",
"    for (cc in intersect(targets, present)) {",
"        ACTIVE_COUNTRY <<- cc",
"        if (!is.null(find_canonical(\"PISA\", year, c(\"W\", \"SCHOOL\", \"PROGRAM\", \"DEMO_LANGUAGE\", \"DEMO_MIGRATION\")))) ",
"            next",
"        failure <- tryCatch({",
"            d <- rc2_subset_labels(raw, !is.na(codes) & codes == cc)",
"            ids <- rc2_pisa_ids(d, cc)",
"            d$SCHOOL_ID <- ids$school",
"            d$STUDENT_ID <- ids$student",
"            obj <- rc2_canonical(d, \"PISA\", year, cc)",
"            obj <- rc2_add_demographics(obj, d, \"PISA\", year, cc, file.path(OUT, \"audit\"))",
"            idvar <- rc2_choose(names(d), c(\"CNTSTUID\", \"STIDSTD\", \"STUDENTID\", \"STUDENT_ID\"))",
"            obj$data$SOURCE_STUDENT_ID <- if (!is.na(idvar) && nzchar(idvar)) ",
"                rc2_chr(d[[idvar]])",
"            else as.character(obj$data$STUDENT_ID)",
"            obj$data$PROGRAM <- if (\"PROGN\" %in% names(d)) ",
"                rc2_chr(d$PROGN)",
"            else NA_character_",
"            for (n in c(\"DEMO_LANGUAGE\", \"DEMO_MIGRATION\")) if (!n %in% names(obj$data)) ",
"                obj$data[[n]] <- NA_character_",
"            obj$meta$program_variable <- if (\"PROGN\" %in% names(d)) ",
"                \"PROGN\"",
"            else \"\"",
"            save_canonical(obj, \"PISA\", year)",
"            NULL",
"        }, error = function(e) conditionMessage(e))",
"        if (!is.null(failure)) {",
"            assign(paste(year, cc, sep = \"_\"), failure, envir = V9_PISA_ERRORS)",
"            logmsg(\"PISA import held for \", cc, \" / \", year, \": \", failure)",
"        }",
"        gc(FALSE)",
"    }",
"    rm(raw)",
"    gc(FALSE)",
"    invisible(present)",
"}",
"",
"load_pisa_minimal <- function(year) {",
"    need <- c(\"W\", \"SCHOOL\", \"PROGRAM\", \"DEMO_LANGUAGE\", \"DEMO_MIGRATION\")",
"    x <- find_canonical(\"PISA\", year, need)",
"    if (!is.null(x)) ",
"        return(x)",
"    key <- as.character(year)",
"    error_key <- paste(year, ACTIVE_COUNTRY, sep = \"_\")",
"    if (exists(error_key, envir = V9_PISA_ERRORS, inherits = FALSE)) ",
"        stop(get(error_key, envir = V9_PISA_ERRORS))",
"    if (exists(key, envir = V9_PISA_ABSENT, inherits = FALSE) && ACTIVE_COUNTRY %in% get(key, envir = V9_PISA_ABSENT)) ",
"        stop(\"PISA \", year, \": country absent from source: \", ACTIVE_COUNTRY)",
"    if (!ALLOW_RAW_FALLBACK) ",
"        stop(\"No complete PISA canonical cache for \", ACTIVE_COUNTRY, \" / \", year)",
"    tryCatch(v9_prepare_pisa_wave(year), error = function(e) {",
"        assign(key, conditionMessage(e), envir = V9_PISA_WAVE_ERRORS)",
"        stop(e)",
"    })",
"    x <- find_canonical(\"PISA\", year, need)",
"    if (is.null(x)) ",
"        stop(\"PISA \", year, \": no usable selected-country object: \", ACTIVE_COUNTRY)",
"    x",
"}",
"",
"v9_shared_scale <- function() {",
"    if (!is.null(V9_CALIBRATION_ERROR)) ",
"        stop(V9_CALIBRATION_ERROR)",
"    if (is.null(V9_CALIBRATION)) ",
"        V9_CALIBRATION <<- tryCatch(v9_build_shared_scale(), error = function(e) {",
"            V9_CALIBRATION_ERROR <<- conditionMessage(e)",
"            stop(e)",
"        })",
"    V9_CALIBRATION",
"}",
"",
"v9_harmonized_country <- function(country, year = PISA_YEARS) {",
"    if (country == \"NLD\") {",
"        p <- file.path(ROOT, \"26_dashboard_fast_resumable/cache/NLD_COBREROS_FOURWAVE.rds\")",
"        v <- file.path(ROOT, \"26_dashboard_fast_resumable/cache/COBREROS_RECONSTRUCTION_VALIDATION.csv\")",
"        if (file.exists(p) && v9_validation_ok(read_csv_safe(v))) {",
"            if (is.null(V9_LEGACY_SES)) ",
"                V9_LEGACY_SES <<- readRDS(p)",
"            x <- V9_LEGACY_SES",
"            if (is.data.frame(x) && all(c(\"cnt\", \"wave\", \"escs_h4\", \"raw_row\") %in% names(x)) && all(x$cnt == \"NLD\")) ",
"                return(x[x$wave %in% year, ])",
"        }",
"    }",
"    cal <- v9_shared_scale()",
"    if (!country %in% cal$countries) ",
"        stop(\"Cobreros SES not available in locked 34-system calibration: \", country)",
"    paths <- file.path(CACHE, paste0(\"COBREROS_PV_\", country, \"_\", year, \".rds\"))",
"    missing <- year[!file.exists(paths)]",
"    if (length(missing)) {",
"        repo <- ensure_cobreros_repo()",
"        Sys.setenv(PISA_REPO = repo)",
"        AE <- new.env(parent = .GlobalEnv)",
"        sys.source(file.path(repo, \"code/r/R/core.R\"), envir = AE)",
"        targets <- intersect(COUNTRIES, cal$countries)",
"        for (y in missing) {",
"            needed <- targets[!file.exists(file.path(CACHE, paste0(\"COBREROS_PV_\", targets, \"_\", y, \".rds\")))]",
"            logmsg(\"ONE shared Cobreros PV import: \", y, \"; missing countries: \", length(needed))",
"            g <- AE$read_extract(y, c(\"wave\", \"cnt\", AE$allpv))",
"            for (cc in needed) {",
"                pv <- g[cnt == cc]",
"                d <- cal$scale[cal$scale$cnt == cc & cal$scale$wave == y, ]",
"                ix <- match(pv$raw_row, d$raw_row)",
"                if (anyNA(ix) || !nrow(pv)) ",
"                  stop(\"PV-to-scale row mismatch: \", cc, \" / \", y)",
"                data <- cbind(d[ix, ], pv[, AE$allpv, with = FALSE])",
"                packet <- list(schema = V9_SCHEMA, pin = COBREROS_PIN, country = cc, year = y, data = data)",
"                atomic_saveRDS(packet, file.path(CACHE, paste0(\"COBREROS_PV_\", cc, \"_\", y, \".rds\")))",
"            }",
"            rm(g)",
"            gc(FALSE)",
"        }",
"    }",
"    packets <- lapply(paths, readRDS)",
"    if (!all(vapply(packets, function(x) identical(x$schema, V9_SCHEMA) && identical(x$pin, COBREROS_PIN) && identical(x$country, ",
"        country) && all(x$data$cnt == country), logical(1)))) ",
"        stop(\"Country PV cache provenance failed\")",
"    nld <- data.table::rbindlist(lapply(packets, `[[`, \"data\"), fill = TRUE)",
"    cov <- nld[, .(n = .N, escs_coverage = sum(w_fstuwt[is.finite(escs_h4)])/sum(w_fstuwt), hisei_coverage = sum(w_fstuwt[is.finite(hisei)])/sum(w_fstuwt), ",
"        pared_coverage = sum(w_fstuwt[is.finite(pared_c)])/sum(w_fstuwt), homepos_coverage = sum(w_fstuwt[is.finite(homepos_h4)])/sum(w_fstuwt)), ",
"        by = .(cnt, wave)]",
"    atomic_write_csv(cov, file.path(OUT, \"audit\", paste0(\"COBREROS_COVERAGE_\", country, \".csv\")))",
"    nld",
"}",
"",
"v9_decorate <- function(x, country, variant) {",
"    if (!is.list(x)) ",
"        stop(\"Invalid task result\")",
"    for (n in c(\"results\", \"holds\")) if (is.data.frame(x[[n]]) && nrow(x[[n]])) {",
"        if (\"country\" %in% names(x[[n]]) && any(v9_codes(x[[n]]$country) != country)) ",
"            stop(\"Country mismatch in task output\")",
"        x[[n]]$country <- paste0(\"iso3:\", country)",
"        if (n == \"results\") ",
"            x[[n]]$variant <- variant",
"        if (n == \"results\" && \"definition\" %in% names(x[[n]])) {",
"            old <- !is.na(x[[n]]$definition) & x[[n]]$definition == \"same as Dutch assessment language versus other language\"",
"            x[[n]]$definition[old] <- \"same_as_assessment_language_vs_other\"",
"        }",
"    }",
"    if (is.data.frame(x$results) && nrow(x$results)) {",
"        needed <- c(\"estimate\", \"se\", \"ci_low\", \"ci_high\")",
"        if (!all(needed %in% names(x$results))) ",
"            stop(\"Incomplete uncertainty columns in task output\")",
"        values <- as.matrix(x$results[needed])",
"        storage.mode(values) <- \"double\"",
"        bad <- rowSums(!is.finite(values)) > 0 | values[, \"se\"] < 0 | values[, \"ci_low\"] > values[, \"ci_high\"]",
"        if (any(bad)) {",
"            x$unusable_results <- x$results[bad, , drop = FALSE]",
"            h <- x$unusable_results[intersect(c(\"country\", \"survey\", \"year\", \"domain\", \"statistic\", \"group\", \"peer_definition\"), ",
"                names(x$unusable_results))]",
"            h$status <- \"HELD\"",
"            h$reason <- \"Non-finite estimate/uncertainty or invalid interval; original row retained in task RDS unusable_results\"",
"            x$holds <- bind_safe(list(x$holds, h))",
"            x$results <- x$results[!bad, , drop = FALSE]",
"        }",
"    }",
"    x",
"}",
"",
"v9_run_task <- function(id, country, variant, fun, legacy = \"\") {",
"    current <- task_result_path(id)",
"    if (file.exists(current)) {",
"        x <- tryCatch(readRDS(current), error = function(e) NULL)",
"        if (is.list(x) && identical(x$v9_schema, V9_SCHEMA) && identical(x$v9_country, country)) {",
"            CURRENT_RUN_TASKS_V8 <<- unique(c(CURRENT_RUN_TASKS_V8, id))",
"            set_state(id, \"DONE\", \"reused V9 checkpoint\", current)",
"            logmsg(\"REUSE \", id)",
"            return(x)",
"        }",
"        stop(\"Task cache provenance mismatch; retained: \", current)",
"    }",
"    if (country == \"NLD\" && nzchar(legacy) && isTRUE(getOption(\"pisa.fast.reuse_v8\", TRUE))) {",
"        ld <- file.path(ROOT, \"26_dashboard_fast_resumable/cache\")",
"        st <- read_csv_safe(file.path(ld, \"state/TASK_STATUS.csv\"))",
"        p <- file.path(ld, \"tasks\", paste0(legacy, \".rds\"))",
"        k <- if (\"task_id\" %in% names(st)) ",
"            match(legacy, st$task_id)",
"        else NA_integer_",
"        if (!is.na(k) && identical(st$status[k], \"DONE\") && file.exists(p)) {",
"            x <- v9_decorate(readRDS(p), country, variant)",
"            x$v9_schema <- V9_SCHEMA",
"            x$v9_country <- country",
"            x$reused_from <- p",
"            atomic_saveRDS(x, current)",
"            set_state(id, \"DONE\", \"reused unchanged V8 raw-wave task\", current)",
"            CURRENT_RUN_TASKS_V8 <<- unique(c(CURRENT_RUN_TASKS_V8, id))",
"            logmsg(\"REUSE V8 task: \", legacy)",
"            return(x)",
"        }",
"    }",
"    run_task(id, function() {",
"        x <- v9_decorate(fun(), country, variant)",
"        x$v9_schema <- V9_SCHEMA",
"        x$v9_country <- country",
"        x",
"    })",
"}",
"",
"v9_master_rows <- function(x) {",
"    if (!nrow(x)) ",
"        return(data.frame())",
"    z <- x",
"    for (n in c(\"group\", \"definition\", \"unit\", \"family\", \"ses_definition\", \"peer_definition\", \"domain\", \"threshold\")) {",
"        if (!n %in% names(z)) ",
"            z[[n]] <- \"\"",
"        z[[n]] <- as.character(z[[n]])",
"        z[[n]][is.na(z[[n]])] <- \"\"",
"    }",
"    z$domain[z$domain == \"\"] <- \"all\"",
"    z$stat <- z$statistic",
"    peer <- grepl(\"peer_exposure\", z$family)",
"    empty <- z$family == \"\"",
"    z$family[empty] <- ifelse(z$stat[empty] == \"total_high\", \"levels\", \"ses\")",
"    blank <- z$group == \"\"",
"    z$group[blank] <- ifelse(peer[blank], z$stat[blank], ifelse(grepl(\"gap_q4_minus_q1\", z$stat[blank]), \"q4_minus_q1\", ifelse(grepl(\"^q1_\", ",
"        z$stat[blank]), \"q1\", ifelse(grepl(\"^q4_\", z$stat[blank]), \"q4\", \"total\"))))",
"    blank <- z$definition == \"\"",
"    z$definition[blank] <- ifelse(z$ses_definition[blank] != \"\", z$ses_definition[blank], z$family[blank])",
"    blank <- z$unit == \"\"",
"    z$unit[blank] <- ifelse(peer[blank], \"percent\", ifelse(grepl(\"basic|high\", z$stat[blank]), ifelse(grepl(\"gap\", z$stat[blank]), ",
"        \"proportion_difference\", \"proportion\"), \"score_points\"))",
"    high <- grepl(\"_high$\", z$stat) | z$stat %in% c(\"self_high\", \"self_below_high\", \"high_gap_q4_minus_q1\")",
"    basic <- grepl(\"_basic$\", z$stat) | z$stat == \"basic_gap_q4_minus_q1\"",
"    for (i in which(high | basic)) z$threshold[i] <- as.character(thresholds_for(z$survey[i], z$domain[i])[if (high[i]) \"high\" else \"basic\"])",
"    z$edition <- SCRIPT_VERSION",
"    z$status <- \"conditional\"",
"    z$source <- \"country-specific resumable microdata task; see task provenance\"",
"    z$series_key <- do.call(paste, c(z[c(\"survey\", \"domain\", \"stat\", \"group\", \"definition\", \"peer_definition\", \"ses_definition\", ",
"        \"threshold\", \"variant\")], sep = \"|\"))",
"    z$id <- paste0(\"V9_\", gsub(\"[^A-Za-z0-9]\", \"_\", paste(z$country, z$year, z$series_key, sep = \"|\")))",
"    z",
"}",
"",
"v9_comparator <- function(x) {",
"    rows <- list()",
"    holds <- list()",
"    pool <- setdiff(COMMON42, \"iso3:NLD\")",
"    if (!nrow(x)) ",
"        return(list(results = data.frame(), holds = data.frame()))",
"    for (sk in unique(x$series_key[x$country == \"iso3:NLD\"])) for (y in unique(x$year[x$series_key == sk & x$country == \"iso3:NLD\"])) {",
"        z <- x[x$series_key == sk & x$year == y & x$country %in% pool, , drop = FALSE]",
"        z <- z[is.finite(z$estimate), , drop = FALSE]",
"        missing <- setdiff(pool, z$country)",
"        if (length(missing) || anyDuplicated(z$country)) {",
"            holds[[length(holds) + 1L]] <- data.frame(series_key = sk, year = y, expected_n = length(pool), observed_n = length(unique(z$country)), ",
"                reason = if (length(missing)) ",
"                  paste(missing, collapse = \";\")",
"                else \"duplicate country rows\")",
"        }",
"        else rows[[length(rows) + 1L]] <- data.frame(series_key = sk, year = y, comparator_n = length(pool), estimate = mean(z$estimate), ",
"            se = NA_real_, ci_low = NA_real_, ci_high = NA_real_, method = \"Unweighted fixed common-42 minus NLD; point estimate only\")",
"    }",
"    list(results = bind_safe(rows), holds = bind_safe(holds))",
"}",
"",
"load_pirls_minimal <- function(year, require_demo = FALSE) {",
"    need <- c(\"W\", \"SES\", \"SCHOOL\", \"CLASS\")",
"    if (require_demo) ",
"        need <- c(need, \"DEMO_LANGUAGE\", \"DEMO_MIGRATION\")",
"    x <- find_canonical(\"PIRLS\", year, need)",
"    if (!is.null(x)) ",
"        return(x)",
"    if (!ALLOW_RAW_FALLBACK) ",
"        stop(\"No usable PIRLS cache for \", year)",
"    registry_roots <- unique(c(file.path(ROOT, \"22_completion_final_v8\"), file.path(ROOT, \"20_rc2_domains\"), file.path(ROOT, ",
"        \"21_completion_repair_v7\"), file.path(ROOT, \"23_slide_only_completion\"), ROOT))",
"    regs <- character()",
"    direct <- file.path(ROOT, \"PIRLS_dashboard_target_population_audit.csv\")",
"    if (file.exists(direct)) ",
"        regs <- direct",
"    for (rr in registry_roots[registry_roots != ROOT & dir.exists(registry_roots)]) {",
"        z <- list.files(rr, pattern = \"^PIRLS_dashboard_target_population_audit\\\\.csv$\", recursive = TRUE, full.names = TRUE)",
"        if (length(z)) ",
"            regs <- c(regs, z)",
"    }",
"    regs <- unique(regs[file.exists(regs)])",
"    if (!length(regs)) {",
"        pats <- c(file.path(ROOT, \"*\", \"PIRLS_dashboard_target_population_audit.csv\"), file.path(ROOT, \"*\", \"*\", \"PIRLS_dashboard_target_population_audit.csv\"), ",
"            file.path(ROOT, \"*\", \"*\", \"*\", \"PIRLS_dashboard_target_population_audit.csv\"), file.path(ROOT, \"*\", \"*\", \"*\", ",
"                \"*\", \"PIRLS_dashboard_target_population_audit.csv\"))",
"        regs <- unique(unlist(lapply(pats, Sys.glob)))",
"    }",
"    if (!length(regs)) ",
"        stop(\"PIRLS target-population registry ontbreekt in de bekende pipelinefolders. \", \"Er wordt bewust NIET door heel Downloads gezocht. Zet zo nodig \", ",
"            \"options(pisa.fast.source_dirs='C:/pad/naar/bronnen') en start opnieuw.\")",
"    regs <- regs[order(file.info(regs)$mtime, decreasing = TRUE)]",
"    a <- read.csv(regs[1], stringsAsFactors = FALSE, check.names = FALSE)",
"    if (!\"source_country_code\" %in% names(a)) ",
"        a$source_country_code <- substr(toupper(basename(a$local_path)), 4, 6)",
"    excl <- if (\"exclude_dashboard\" %in% names(a)) ",
"        toupper(as.character(a$exclude_dashboard)) %in% c(\"TRUE\", \"T\", \"1\", \"YES\")",
"    else FALSE",
"    z <- a[!excl & as.integer(a$year) == as.integer(year) & toupper(a$source_country_code) == ACTIVE_COUNTRY, , drop = FALSE]",
"    if (nrow(z) != 1L) ",
"        stop(\"PIRLS \", year, \": geen unieke main-study bron.\")",
"    p <- rc2_relocate(z$local_path[1], ROOT)",
"    h <- rc2_header(p)",
"    bv <- rc2_books_var(h)",
"    keep <- h$upper %in% c(\"IDCNTRY\", \"IDSCHOOL\", \"IDCLASS\", \"IDSTUD\", \"IDSTUDS\", \"TOTWGT\", \"JKZONE\", \"JKREP\", \"ASDAGE\", ",
"        \"ASDGAGE\", \"ASBGAGE\", \"AGE\", \"IDGRADE\", \"ITSEX\", \"ASBG01\", \"ASBGSEX\", bv) | grepl(\"^ASRREA0[1-5]$\", h$upper) | h$variable %in% ",
"        rc2_demo_candidates(h)",
"    raw <- rc2_read_selected(p, h$variable[keep])",
"    raw <- as.data.frame(lapply(raw, rc2_clean_labeled))",
"    obj <- rc2_canonical(raw, \"PIRLS\", year, ACTIVE_COUNTRY)",
"    obj <- rc2_attach_and_drop(obj, \"PIRLS\", year, ACTIVE_COUNTRY, file.path(OUT, \"audit\"))",
"    obj <- normalize_canonical_meta(obj, \"PIRLS\", year)",
"    save_canonical(obj, \"PIRLS\", year)",
"    obj",
"}",
"",
"load_timss_minimal <- function(year, require_demo = FALSE) {",
"    need <- c(\"W\", \"SES\", \"SCHOOL\", \"CLASS\")",
"    if (require_demo) ",
"        need <- c(need, \"DEMO_LANGUAGE\", \"DEMO_MIGRATION\")",
"    x <- find_canonical(\"TIMSS\", year, need)",
"    if (!is.null(x)) ",
"        return(x)",
"    if (!ALLOW_RAW_FALLBACK) ",
"        stop(\"No usable TIMSS cache for \", year)",
"    rec <- v9_timss_sources(year, INV, file.path(CACHE, \"timss_sources\"), file.path(CACHE, \"timss_extracts\"), allow_download = FALSE)",
"    rec <- rec[toupper(rec$source_country_code) == ACTIVE_COUNTRY, , drop = FALSE]",
"    if (!nrow(rec)) ",
"        stop(\"TIMSS \", year, \": bron niet gevonden voor \", ACTIVE_COUNTRY)",
"    a <- rc2_prepare_iea(rec, file.path(CACHE, \"timss_canonical\"), file.path(OUT, \"audit\"), file.path(CACHE, \"timss_sources\"), ",
"        numeracy = NULL)",
"    if (nrow(a$tasks) != 1L) ",
"        stop(\"TIMSS \", year, \": geen unieke canonical taak voor \", ACTIVE_COUNTRY)",
"    obj <- readRDS(a$tasks$path[1])",
"    obj <- normalize_canonical_meta(obj, \"TIMSS\", year)",
"    save_canonical(obj, \"TIMSS\", year)",
"    obj",
"}",
"",
"pisa_program_map <- function(year) {",
"    p <- file.path(CACHE, paste0(\"PISA_PROGRAM_MAP_\", ACTIVE_COUNTRY, \"_\", year, \".rds\"))",
"    if (file.exists(p)) ",
"        return(readRDS(p))",
"    obj <- tryCatch(load_pisa_minimal(year), error = function(e) e)",
"    if (inherits(obj, \"error\")) {",
"        logmsg(\"PISA \", year, \": PROGRAM map unavailable (\", conditionMessage(obj), \"); whole-school Cobreros outputs will continue.\")",
"        return(data.frame(student_id = character(), school = character(), program = character(), stringsAsFactors = FALSE))",
"    }",
"    d <- obj$data",
"    id <- if (\"SOURCE_STUDENT_ID\" %in% names(d)) ",
"        as.character(d$SOURCE_STUDENT_ID)",
"    else if (\"STUDENT_ID\" %in% names(d)) ",
"        as.character(d$STUDENT_ID)",
"    else as.character(seq_len(nrow(d)))",
"    out <- data.frame(student_id = id, school = as.character(d$SCHOOL), program = if (\"PROGRAM\" %in% names(d)) ",
"        as.character(d$PROGRAM)",
"    else NA_character_, stringsAsFactors = FALSE)",
"    saveRDS(out, p, compress = FALSE)",
"    out",
"}",
"",
"v9_build_shared_scale <- function() {",
"    cache_path <- file.path(CACHE, \"COBREROS_SCALE34_V9.rds\")",
"    legacy_scale <- file.path(ROOT, \"27_dashboard_multicountry_v9/cache/COBREROS_SCALE34_V9.rds\")",
"    if (!file.exists(cache_path) && file.exists(legacy_scale)) cache_path <- legacy_scale",
"    validation_path <- file.path(CACHE, \"COBREROS_RECONSTRUCTION_VALIDATION.csv\")",
"    if (file.exists(cache_path)) {",
"        x <- readRDS(cache_path)",
"        if (is.list(x) && identical(x$schema, V9_SCHEMA) && identical(x$pin, COBREROS_PIN) && v9_validation_ok(x$validation) && ",
"            length(x$countries) == 34L) ",
"            return(x)",
"        stop(\"Shared calibration cache has incompatible provenance; original left intact: \", cache_path)",
"    }",
"    ensure_packages(c(\"data.table\", \"arrow\", \"Rcpp\", \"jsonlite\", \"digest\", \"tidyselect\"))",
"    repo <- ensure_cobreros_repo()",
"    Sys.setenv(PISA_REPO = repo)",
"    AE <- new.env(parent = .GlobalEnv)",
"    for (f in c(\"core\", \"irt\", \"analyses\")) sys.source(file.path(repo, \"code/r/R\", paste0(f, \".R\")), envir = AE)",
"    param_path <- file.path(repo, \"results/r/tables/irt_parameters_four_cycles.csv\")",
"    if (!file.exists(param_path)) ",
"        stop(\"Pinned author parameter table missing\")",
"    par <- data.table::fread(param_path)",
"    a <- par$a",
"    b <- lapply(par$steps, jsonlite::fromJSON)",
"    names(a) <- par$item",
"    names(b) <- par$item",
"    oldcols <- c(\"st011q02ta\", \"st011q04ta\", \"st011q05ta\", \"st011q06ta\", \"st011q09ta\", \"st012q09na\", \"st012q02ta\", \"st012q03ta\", ",
"        \"st012q01ta\", \"st012q07na\", \"st012q08na\", \"st012q06na\", \"books6\")",
"    newcols <- c(\"st250q01ja\", \"st250q02ja\", \"st250q03ja\", \"st250q05ja\", \"st251q07ja\", \"st251q06ja\", \"st251q01ja\", \"st251q03ja\", ",
"        \"st254q01ja\", \"st254q04ja\", \"st254q05ja\", \"st254q02ja\", \"st254q03ja\", \"st255q01ja\")",
"    basecols <- c(\"wave\", \"cnt\", \"cntstuid\", \"cntschid\", \"w_fstuwt\", \"hisei\", \"paredint\", \"hisced\")",
"    years <- c(2015L, 2018L, 2022L, 2025L)",
"    parts <- lapply(years, function(y) {",
"        logmsg(\"Cobreros minimal-column input: \", y)",
"        cols <- unique(c(basecols, if (y <= 2018) oldcols else newcols))",
"        g <- AE$read_extract(y, cols)",
"        g[, `:=`(supplement, FALSE)]",
"        it <- AE$recode_four(g)",
"        cbind(g[, c(\"wave\", \"cnt\", \"cntstuid\", \"cntschid\", \"raw_row\", \"w_fstuwt\", \"hisei\", \"paredint\", \"hisced\"), with = FALSE], ",
"            it)",
"    })",
"    common <- setdiff(Reduce(intersect, lapply(parts, function(g) unique(g$cnt))), \"CRI\")",
"    if (length(common) != 34L) ",
"        stop(\"Unexpected Cobreros four-wave sample size: \", length(common), \" (expected 34)\")",
"    d <- data.table::rbindlist(parts, fill = TRUE)",
"    rm(parts)",
"    d <- d[cnt %in% common]",
"    gc(FALSE)",
"    mapping <- d[wave == 2018 & is.finite(hisced) & is.finite(paredint), .(years = as.numeric(names(sort(table(paredint), ",
"        decreasing = TRUE))[1])), by = hisced]",
"    d[wave == 2015, `:=`(paredint, mapping$years[match(hisced, mapping$hisced)])]",
"    d[, `:=`(pared_c, data.table::fifelse(paredint == 3, 6, data.table::fifelse(paredint == 14.5, 14, paredint)))]",
"    items <- par$item",
"    X <- as.matrix(d[, ..items])",
"    storage.mode(X) <- \"integer\"",
"    X[is.na(X)] <- -1L",
"    logmsg(\"Fixed-parameter 13-item HOMEPOS scoring (no IRT refit)\")",
"    resolve_wle_fun <- if (exists(\"resolve_wle\", envir = AE, inherits = FALSE) && is.function(AE$resolve_wle)) ",
"        AE$resolve_wle",
"    else NULL",
"    wle_cpp_fun <- if (exists(\"wle_cpp\", envir = AE, inherits = FALSE) && is.function(AE$wle_cpp)) ",
"        AE$wle_cpp",
"    else if (exists(\"wle_cpp\", envir = .GlobalEnv, inherits = FALSE) && is.function(get(\"wle_cpp\", envir = .GlobalEnv, inherits = FALSE))) ",
"        get(\"wle_cpp\", envir = .GlobalEnv, inherits = FALSE)",
"    else NULL",
"    if (!is.function(resolve_wle_fun)) ",
"        stop(\"Cobreros resolve_wle function not available after sourcing irt.R\")",
"    if (!is.function(wle_cpp_fun)) ",
"        stop(\"Cobreros compiled wle_cpp function not available after sourceCpp; check Rtools/Rcpp build\")",
"    sc <- resolve_wle_fun(wle_cpp_fun(X, a, b, min_items = 3), X, a, b)",
"    eligible <- rowSums(X >= 0) >= 8",
"    if (any(eligible & (!sc$converged | sc$boundary))) ",
"        stop(\"Unresolved WLE scores in fixed-parameter reconstruction\")",
"    home <- sc$theta",
"    home[!eligible] <- NA_real_",
"    rm(X, sc)",
"    gc(FALSE)",
"    w <- AE$senate(d)",
"    raw <- cbind(d$hisei, d$pared_c, home)",
"    d[, `:=`(escs_h4, AE$escs(raw, AE$cell_id(d), w)$score)]",
"    d[, `:=`(homepos_h4, AE$zscore(home, w))]",
"    rm(raw, home, w)",
"    gc(FALSE)",
"    committed <- data.table::fread(file.path(repo, \"results/r/tables/gap_series_math.csv\"))",
"    committed <- committed[index == \"escs_h4\"]",
"    val <- list()",
"    for (y in years) {",
"        gy <- AE$read_extract(y, c(\"wave\", \"cnt\", \"w_fstuwt\", AE$pvcols(\"math\")))",
"        gy <- gy[cnt %in% common]",
"        ix <- match(paste(gy$wave, gy$cnt, gy$raw_row), paste(d$wave, d$cnt, d$raw_row))",
"        if (anyNA(ix)) ",
"            stop(\"Cobreros validation row match failed\")",
"        gy[, `:=`(escs_h4, d$escs_h4[ix])]",
"        gaps <- gy[, {",
"            W <- matrix(w_fstuwt, ncol = 1)",
"            P <- as.matrix(.SD)",
"            code <- v8_quantile_codes(AE, escs_h4, W, P)[, 1]",
"            valid <- is.finite(code)",
"            code <- code[valid]",
"            P <- P[valid, , drop = FALSE]",
"            ww <- w_fstuwt[valid]",
"            mu <- vapply(0:3, function(q) mean(vapply(seq_len(ncol(P)), function(m) weighted.mean(P[code == q, m], ww[code == ",
"                q], na.rm = TRUE), numeric(1))), numeric(1))",
"            list(gap = mu[4] - mu[1])",
"        }, by = cnt, .SDcols = AE$pvcols(\"math\")]",
"        if (nrow(gaps) != 34L || any(!is.finite(gaps$gap))) ",
"            stop(\"Incomplete 34-system Cobreros validation in \", y)",
"        ours <- mean(gaps$gap)",
"        target <- as.numeric(committed[[paste0(\"y\", y)]][1])",
"        val[[length(val) + 1L]] <- data.frame(domain = \"mathematics\", year = y, reconstructed = ours, committed_R = target, ",
"            abs_diff = abs(ours - target), stringsAsFactors = FALSE)",
"        rm(gy, gaps)",
"        gc(FALSE)",
"    }",
"    validation <- bind_safe(val)",
"    atomic_write_csv(validation, validation_path)",
"    if (any(!is.finite(validation$abs_diff)) || max(validation$abs_diff, na.rm = TRUE) > 0.35) ",
"        stop(\"Cobreros reconstruction validation failed; max absolute gap difference = \", max(validation$abs_diff, na.rm = TRUE))",
"    keep <- c(\"wave\", \"cnt\", \"cntstuid\", \"cntschid\", \"raw_row\", \"w_fstuwt\", \"escs_h4\", \"hisei\", \"pared_c\", \"homepos_h4\")",
"    d <- d[, keep, with = FALSE]",
"    x <- list(schema = V9_SCHEMA, pin = COBREROS_PIN, countries = sort(common), validation = validation, scale = d)",
"    atomic_saveRDS(x, cache_path)",
"    x",
"}",
"",
"pisa_harmonized_outputs <- function(nld) {",
"    repo <- file.path(DOWNLOADS, \"pisa_2025_cobreros\")",
"    Sys.setenv(PISA_REPO = repo)",
"    AE <- new.env(parent = .GlobalEnv)",
"    sys.source(file.path(repo, \"code/r/R/core.R\"), envir = AE)",
"    ses_rows <- list()",
"    peer_rows <- list()",
"    holds <- list()",
"    years <- sort(unique(nld$wave))",
"    for (y in years) {",
"        logmsg(paste0(\"PISA harmonized SES \", ACTIVE_COUNTRY, \" outputs: \"), y)",
"        g <- data.table::as.data.table(nld[nld$wave == y, ])",
"        W <- AE$weights_for(g)",
"        ses_codes <- v8_quantile_codes(AE, g$escs_h4, W)",
"        R <- ncol(W) - 1L",
"        pm <- pisa_program_map(y)",
"        aid <- as.character(g$cntstuid)",
"        pid <- as.character(pm$student_id)",
"        if (anyDuplicated(pid)) ",
"            stop(\"Duplicate released student IDs in PROGRAM map: \", ACTIVE_COUNTRY, \" / \", y)",
"        if (length(pid)) {",
"            mm <- match(aid, pid)",
"            match_rate <- mean(!is.na(mm))",
"        }",
"        else {",
"            mm <- rep(NA_integer_, length(aid))",
"            match_rate <- 0",
"        }",
"        school <- as.character(g$cntschid)",
"        program <- if (match_rate >= 0.95) ",
"            pm$program[mm]",
"        else rep(NA_character_, nrow(g))",
"        if (match_rate < 0.95) ",
"            logmsg(\"PISA \", y, \": PROGRAM match only \", round(100 * match_rate, 1), \"%; direct-learning-environment peer output is held; whole-school continues.\")",
"        direct <- ifelse(!is.na(program) & nzchar(program), paste(school, program, sep = \"::PROGN::\"), NA_character_)",
"        domain_map <- c(math = \"mathematics\", read = \"reading\", scie = \"science\")",
"        for (adom in names(domain_map)) {",
"            label <- unname(domain_map[[adom]])",
"            P <- as.matrix(g[, AE$pvcols(adom), with = FALSE])",
"            codes <- v8_quantile_codes(AE, g$escs_h4, W, P)",
"            included <- attr(codes, \"included\")",
"            atomic_write_csv(data.frame(year = y, domain = label, n_total = nrow(g), n_included = sum(included), weight_coverage = sum(W[included, ",
"                1])/sum(W[, 1])), file.path(OUT, \"audit\", paste0(\"COBREROS_SAMPLE_\", ACTIVE_COUNTRY, \"_\", y, \"_\", adom, \".csv\")))",
"            th <- thresholds_for(\"PISA\", label)",
"            final <- matrix(NA_real_, nrow = 10, ncol = 6)",
"            colnames(final) <- c(\"q1_mean\", \"q4_mean\", \"q1_basic\", \"q4_basic\", \"q1_high\", \"q4_high\")",
"            reps <- array(NA_real_, c(R, 10, 6))",
"            calc_groups <- function(m, rcol) {",
"                code <- codes[, rcol]",
"                w <- W[, rcol]",
"                yy <- P[, m]",
"                q1 <- code == 0",
"                q4 <- code == 3",
"                c(weighted_mean(yy[q1], w[q1]), weighted_mean(yy[q4], w[q4]), weighted_mean(as.numeric(yy[q1] >= th[\"basic\"]), ",
"                  w[q1]), weighted_mean(as.numeric(yy[q4] >= th[\"basic\"]), w[q4]), weighted_mean(as.numeric(yy[q1] >= th[\"high\"]), ",
"                  w[q1]), weighted_mean(as.numeric(yy[q4] >= th[\"high\"]), w[q4]))",
"            }",
"            for (m in 1:10) {",
"                final[m, ] <- calc_groups(m, 1)",
"                for (r in 1:R) reps[r, m, ] <- calc_groups(m, r + 1)",
"            }",
"            sm <- author_summarise_matrix(final, reps)",
"            for (k in seq_len(ncol(final))) ses_rows[[length(ses_rows) + 1L]] <- data.frame(survey = \"PISA\", year = y, domain = label, ",
"                statistic = colnames(final)[k], estimate = sm$estimate[k], se = sm$se[k], ci_low = sm$estimate[k] - 1.96 * ",
"                  sm$se[k], ci_high = sm$estimate[k] + 1.96 * sm$se[k], ses_definition = \"Cobreros_fourwave_13item_trend_comparable\", ",
"                stringsAsFactors = FALSE)",
"            for (pair in list(c(\"q1_mean\", \"q4_mean\", \"score_gap_q4_minus_q1\"), c(\"q1_basic\", \"q4_basic\", \"basic_gap_q4_minus_q1\"), ",
"                c(\"q1_high\", \"q4_high\", \"high_gap_q4_minus_q1\"))) {",
"                i1 <- match(pair[1], colnames(final))",
"                i4 <- match(pair[2], colnames(final))",
"                cvec <- rep(0, ncol(final))",
"                cvec[i1] <- -1",
"                cvec[i4] <- 1",
"                est <- sum(sm$estimate * cvec)",
"                se <- sqrt(drop(t(cvec) %*% sm$covariance %*% cvec))",
"                ses_rows[[length(ses_rows) + 1L]] <- data.frame(survey = \"PISA\", year = y, domain = label, statistic = pair[3], ",
"                  estimate = est, se = se, ci_low = est - 1.96 * se, ci_high = est + 1.96 * se, ses_definition = \"Cobreros_fourwave_13item_trend_comparable\", ",
"                  stringsAsFactors = FALSE)",
"            }",
"        }",
"        codes <- ses_codes",
"        for (pd in c(\"whole_school\", \"direct_learning_environment\")) {",
"            unit <- if (pd == \"whole_school\") ",
"                school",
"            else direct",
"            if (!any(!is.na(unit) & nzchar(unit))) {",
"                holds[[length(holds) + 1L]] <- data.frame(survey = \"PISA\", year = y, domain = \"all\", family = \"ses_peer_exposure\", ",
"                  peer_definition = pd, status = \"HELD\", reason = \"No valid peer unit; released student-ID PROGRAM match must be at least 95%\", ",
"                  stringsAsFactors = FALSE)",
"                next",
"            }",
"            one <- function(rcol) {",
"                code <- codes[, rcol]",
"                w <- W[, rcol]",
"                q1 <- as.numeric(code == 0)",
"                q4 <- as.numeric(code == 3)",
"                c(q1_target_pct_q4_peers = 100 * peer_share(unit, q4, q1, w), q4_target_pct_q1_peers = 100 * peer_share(unit, ",
"                  q1, q4, w))",
"            }",
"            full <- one(1)",
"            reps <- sapply(2:ncol(W), one)",
"            if (is.vector(reps)) ",
"                reps <- matrix(reps, nrow = 2)",
"            se <- sqrt(rowSums((reps - full)^2)/(80 * 0.25))",
"            for (k in 1:2) peer_rows[[length(peer_rows) + 1L]] <- data.frame(survey = \"PISA\", year = y, domain = \"\", family = \"ses_peer_exposure\", ",
"                peer_definition = pd, statistic = names(full)[k], estimate = full[k], se = se[k], ci_low = full[k] - 1.96 * ",
"                  se[k], ci_high = full[k] + 1.96 * se[k], ses_definition = \"Cobreros_fourwave_13item_trend_comparable\", ",
"                stringsAsFactors = FALSE)",
"        }",
"        gc(FALSE)",
"    }",
"    list(ses = bind_safe(ses_rows), peers = bind_safe(peer_rows), holds = bind_safe(holds))",
"}",
"",
"bind_safe <- function(x) {",
"    x <- Filter(function(z) is.data.frame(z) && nrow(z) > 0, x)",
"    if (!length(x)) ",
"        return(data.frame())",
"    as.data.frame(data.table::rbindlist(x, use.names = TRUE, fill = TRUE))",
"}",
"",
"find_existing_master <- function() {",
"    explicit <- getOption(\"pisa.fast.master\", \"\")",
"    if (nzchar(explicit)) {",
"        if (!file.exists(explicit)) ",
"            stop(\"Configured master not found: \", explicit)",
"        return(norm(explicit))",
"    }",
"    roots <- unique(c(ROOT, DOWNLOADS, getOption(\"pisa.fast.master_dirs\", character())))",
"    ff <- unique(unlist(lapply(roots[dir.exists(roots)], function(r) unlist(lapply(0:4, function(k) c(Sys.glob(file.path(r, ",
"        paste(rep(\"*\", k), collapse = \"/\"), \"*MASTER*.csv*\")), Sys.glob(file.path(r, paste(rep(\"*\", k), collapse = \"/\"), ",
"        \"FINAL_PRODUCT_BASIS*.csv*\"))))))))",
"    ff <- ff[grepl(\"RESULTATEN_MASTER(_MET_V8)?\\\\.csv(\\\\.gz)?$|FINAL_PRODUCT_BASIS\\\\.csv(\\\\.gz)?$\", basename(ff), ignore.case = TRUE)]",
"    ff <- ff[!grepl(\"27_dashboard_multicountry_v9\", ff, fixed = TRUE)]",
"    if (!length(ff)) {",
"        zz <- unique(c(getOption(\"pisa.fast.master_archive\", character()), list.files(DOWNLOADS, pattern = \"^(PISA_V8_AFGEROND_PAKKET_20260930|OVERDRACHT_PROJECTPRODUCTEN_20260927).*\\\\.zip$\", ",
"            full.names = TRUE, ignore.case = TRUE)))",
"        zz <- zz[file.exists(zz)]",
"        if (length(zz)) ",
"            zz <- zz[order(!grepl(\"V8_AFGEROND\", basename(zz)), -as.numeric(file.info(zz)$mtime))]",
"        for (p in zz) {",
"            members <- tryCatch(unzip(p, list = TRUE)$Name, error = function(e) character())",
"            members <- members[grepl(\"(^|/)RESULTATEN_MASTER(_MET_V8)?\\\\.csv$\", members) & !grepl(\"(^|/)\\\\.\\\\.(/|$)\", members)]",
"            if (!length(members)) ",
"                next",
"            member <- members[order(!grepl(\"MET_V8\", members), nchar(members))][1]",
"            dest <- file.path(CACHE, \"master_inputs\", unname(tools::md5sum(p)))",
"            target <- file.path(dest, member)",
"            if (!file.exists(target)) {",
"                dir.create(dest, recursive = TRUE, showWarnings = FALSE)",
"                unzip(p, files = member, exdir = dest)",
"            }",
"            if (file.exists(target)) ",
"                return(norm(target))",
"        }",
"        return(\"\")",
"    }",
"    ff[order(!grepl(\"MET_V8\", basename(ff)), -as.numeric(file.info(ff)$mtime))][1]",
"}",
"",
"read_master <- function(path) {",
"    if (!nzchar(path)) ",
"        return(data.frame())",
"    logmsg(\"Preserved existing master: \", path)",
"    if (grepl(\"\\\\.gz$\", path)) {",
"        con <- gzfile(path, \"rt\")",
"        on.exit(close(con))",
"        read.csv(con, check.names = FALSE)",
"    }",
"    else data.table::fread(path, data.table = FALSE, showProgress = FALSE)",
"}",
"",
"v9_years <- function(option, default, allowed) {",
"    x <- getOption(option, default)",
"    if (!is.numeric(x) || anyNA(x) || !length(x) || any(!x %in% allowed)) ",
"        stop(\"Unsupported years in \", option, \"; retained historical results are exported separately\")",
"    sort(unique(as.integer(x)))",
"}",
"",
"v9_collect <- function(x, cc) {",
"    if (is.data.frame(x$results) && nrow(x$results)) ",
"        NEW_RESULTS[[length(NEW_RESULTS) + 1L]] <<- x$results",
"    if (is.data.frame(x$holds) && nrow(x$holds)) {",
"        if (!\"country\" %in% names(x$holds)) ",
"            x$holds$country <- paste0(\"iso3:\", cc)",
"        HOLDS[[length(HOLDS) + 1L]] <<- x$holds",
"    }",
"}",
"",
"v9_checkpoint <- function(force = FALSE) {",
"    interval <- getOption(\"pisa.fast.csv_checkpoint_seconds\", 300)",
"    if (!is.numeric(interval) || length(interval) != 1L || !is.finite(interval) || interval < 0) ",
"        stop(\"Invalid CSV checkpoint interval\")",
"    now <- as.numeric(Sys.time())",
"    if (!force && now - LAST_CSV_CHECKPOINT < interval) ",
"        return(invisible(NULL))",
"    atomic_write_csv(bind_safe(NEW_RESULTS), file.path(OUT, \"COUNTRIES_NEW_OR_REUSED_TASK_RESULTS.csv\"))",
"    atomic_write_csv(bind_safe(HOLDS), file.path(OUT, \"COUNTRIES_AVAILABILITY_HOLDS.csv\"))",
"    LAST_CSV_CHECKPOINT <<- now",
"}",
""
),collapse="\n")
eval(parse(text=V10_BACKEND_FUNCTIONS), envir=.GlobalEnv)
# PISA/PIRLS/TIMSS V10. Single downloadable script; legacy backend included below.
# source(file.path(path.expand('~/Downloads'),'PISA_RESULTATEN_RESUME_V11_20261001.R'))
# Optional unattended choice: options(pisa.fast.run_mode=1L) (1 NL, 2 comparators,
# 3 other countries, 4 all). Choice 2 excludes NL; the fixed reference excludes NL.
# Does not edit the dashboard or PowerPoint. It supplies explicit data contracts.

V10_VERSION <- 'V11_20261001_1'
V10_CONTRACT <- 'slide_results_1'
COMMON42 <- c('ALB','ARE','AUS','AZE','BGR','BRA','CYP','CZE','DEU','DNK','ESP','FIN','FRA','GEO',
 'HUN','IRL','ITA','JOR','KAZ','LTU','LVA','MAR','MKD','MNE','NLD','NOR','NZL','POL','PRT','QAT',
 'SAU','SGP','SRB','SVK','SVN','SWE','TUR','TWN','USA','HKG','MAC','XKX')
COBREROS_PIN <- '1da4b26097e84e732973af672355a1c3103d5d33'
COBREROS_REPO_URL <- 'https://github.com/Innovamat-Research-Lab/pisa_2025.git'
V9_SCHEMA <- 'v9-country-isolation-1'

v10_text <- function(x) {x<-as.character(x);x[is.na(x)]<-'';x}
v10_codes <- function(x) unique(toupper(sub('^iso3:','',v10_text(x),ignore.case=TRUE)))
v10_bind <- function(xs) {
 xs<-Filter(function(x)is.data.frame(x)&&nrow(x)>0,xs)
 if(!length(xs))return(data.frame())
 if(requireNamespace('data.table',quietly=TRUE))return(as.data.frame(data.table::rbindlist(xs,fill=TRUE)))
 nn<-unique(unlist(lapply(xs,names)));do.call(rbind,lapply(xs,function(x){for(n in setdiff(nn,names(x)))x[[n]]<-NA;x[nn]}))
}
bind_safe <- v10_bind
v10_read <- function(p) {
 if(!file.exists(p))return(data.frame())
 if(isTRUE(file.info(p)$size<=4))return(data.frame())
 if(requireNamespace('data.table',quietly=TRUE)&&!grepl('\\.gz$',p))return(as.data.frame(data.table::fread(p,showProgress=FALSE)))
 read.csv(p,check.names=FALSE,stringsAsFactors=FALSE,fileEncoding='UTF-8-BOM')
}
v10_write <- function(x,p) {
 dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE)
 tmp<-tempfile(tmpdir=dirname(p));write.csv(x,tmp,row.names=FALSE,na='',fileEncoding='UTF-8')
 # Windows cannot rename over an existing file. Keep the last version until commit.
 old<-paste0(p,'.previous');if(file.exists(old))unlink(old)
 if(file.exists(p)&&!file.rename(p,old))stop('Cannot preserve old registry: ',p)
 if(!file.rename(tmp,p)){if(file.exists(old))file.rename(old,p);stop('Cannot commit: ',p)}
 invisible(p)
}
v10_save_rds <- function(x,p) {
 dir.create(dirname(p),recursive=TRUE,showWarnings=FALSE);tmp<-tempfile(tmpdir=dirname(p));saveRDS(x,tmp)
 old<-paste0(p,'.previous');if(file.exists(old))unlink(old)
 if(file.exists(p)&&!file.rename(p,old))stop('Cannot preserve previous checkpoint: ',p)
 if(!file.rename(tmp,p)){if(file.exists(old))file.rename(old,p);stop('Cannot commit checkpoint: ',p)}
 invisible(p)
}
v10_key <- function(x,include_country=TRUE) {
 cols<-c(if(include_country)'country','survey','year','domain','module','stat','group',
         'definition','peer_definition','threshold','unit','calculation_policy')
 do.call(paste,c(lapply(cols,function(n)if(n%in%names(x))v10_text(x[[n]]) else rep('',nrow(x))),sep='|'))
}
v10_fingerprint <- function(p) {
 if(!file.exists(p))return('missing')
 f<-file.info(p);paste(f$size,as.numeric(f$mtime),sep=':')
}
v10_once <- function(env,key,fun) {
 if(exists(key,envir=env,inherits=FALSE))return(get(key,envir=env,inherits=FALSE))
 x<-fun();assign(key,x,envir=env);x
}
v10_choice <- function(mode,available,custom=NULL) {
 fixed<-V11_OECD37;available<-sort(v10_codes(available));available<-available[grepl('^[A-Z]{3}$',available)]
 if(!is.null(custom))return(v10_codes(custom))
 switch(as.character(mode),'1'='NLD','2'=fixed,'3'=setdiff(available,c('NLD',fixed)),
        '4'=unique(c('NLD',fixed,available)),stop('Keuze moet 1, 2, 3 of 4 zijn.'))
}
v10_menu <- function() {
 custom<-getOption('pisa.fast.countries',NULL)
 if(!is.null(custom)) {if(!length(custom)||any(!grepl('^[A-Z]{3}$',v10_codes(custom))))stop('Ongeldige landcodes');return(0L)}
 k<-getOption('pisa.fast.run_mode',NULL)
 if(is.null(k)) {
  if(!interactive())stop('Zet options(pisa.fast.run_mode=1L), of start interactief.')
  cat('\n1 Nederland\n2 Vaste vergelijkingslanden (zonder NL)\n3 Overige landen\n4 Alles\n')
  k<-readline('Keuze [1]: ');if(!nzchar(k))k<-'1';k<-suppressWarnings(as.numeric(k))
 }
 if(length(k)!=1L||!is.finite(k)||!k%in%1:4)stop('Keuze moet een geheel getal 1 t/m 4 zijn.')
 as.integer(k)
}

# One-time adapter. It only recognises explicitly recorded constructs. Unknown
# definitions remain in SOURCE_INVENTORY and are never silently adopted.
v10_adapt <- function(z,path,script='unknown',priority=50L) {
 if(!nrow(z))return(data.frame())
 z$locator_row<-seq_len(nrow(z))
 if(all(c('outcome','split_group','definition_id')%in%names(z))) {
  # Read exported dashboard observations as sources, without modifying its UI.
  # Reference lines carry the country's profile ID but are NOT country estimates.
  if('series_role'%in%names(z))z<-z[!grepl('compar|reference_mean|international_position',z$series_role),,drop=FALSE]
  if(!nrow(z))return(data.frame())
  o<-v10_text(z$outcome);g<-v10_text(z$split_group)
  z$group<-g;z$definition<-z$definition_id;z$ses_definition<-z$ses_definition_id
  z$threshold<-z$threshold_id;z$variant<-z$source_variant;z$source<-z$source_id
  z$status<-tolower(v10_text(z$quality_status));z$stat<-o;z$family<-''
  core<-o%in%c('mean_score','p10','p50','p90','p90_minus_p10','high_proficiency')
  z$family[core]<-'levels';z$group[core]<-'total'
  z$stat[o=='mean_score']<-'mean';z$stat[o=='p90_minus_p10']<-'p90_p10';z$stat[o=='high_proficiency']<-'total_high'
  ses<-o%in%c('ses_mean_levels','ses_basic_levels','ses_high_levels','ses_score_gap');z$family[ses]<-'ses'
  z$stat[o=='ses_mean_levels']<-paste0(g[o=='ses_mean_levels'],'_mean')
  z$stat[o=='ses_basic_levels']<-paste0(g[o=='ses_basic_levels'],'_basic')
  z$stat[o=='ses_high_levels']<-paste0(g[o=='ses_high_levels'],'_high')
  z$stat[o=='ses_score_gap']<-'score_gap_q4_minus_q1'
  z$family[o=='gender_mean_levels']<-'gender';z$stat[o=='gender_mean_levels']<-'mean';z$definition[o=='gender_mean_levels']<-'gender'
  p<-o%in%c('ses_peer_exposure','high_proficiency_peer_exposure','migration_peer_exposure');z$family[p]<-o[p];z$stat[p]<-g[p]
  mi<-o%in%c('migration_mean_levels','migration_gap_vs_native');z$family[mi]<-'migration_generation'
  z$stat[o=='migration_mean_levels']<-'mean_score';z$stat[o=='migration_gap_vs_native']<-'mean_score_gap'
  lm<-o=='home_language_mean_levels';z$family[lm]<-'language';z$stat[lm]<-'mean'
  # Dashboard percentages of high/basic proficiency are converted back to the
  # original estimator proportions; score/peer units are unaffected.
  # A prior dashboard export mislabeled the V8 Cobreros fractions as percent
  # while retaining the original fractions. These ambiguous view rows are not
  # adopted: recover the exact units from the underlying V8/master output.
  ambiguous_rate<-o%in%c('ses_basic_levels','ses_high_levels')&z$definition=='Cobreros_fourwave_13item_trend_comparable'&z$unit=='percent'&as.numeric(z$estimate)>=0&as.numeric(z$estimate)<=1
  z$family[ambiguous_rate]<-''
  rate<-o%in%c('high_proficiency','ses_basic_levels','ses_high_levels')&z$unit=='percent'&!ambiguous_rate
  for(n in c('estimate','se','ci_low','ci_high'))z[[n]][rate]<-as.numeric(z[[n]][rate])/100
  z$unit[rate]<-'proportion'
  z<-z[!ambiguous_rate,,drop=FALSE]
 }
 if('country_id'%in%names(z)&&!'country'%in%names(z))z$country<-z$country_id
 if('statistic'%in%names(z)&&!'stat'%in%names(z))z$stat<-z$statistic
 for(n in c('country','survey','year','domain','stat','group','definition','family','unit',
            'peer_definition','ses_definition','threshold','variant','source','status')) {
  if(!n%in%names(z))z[[n]]<-'';z[[n]]<-v10_text(z[[n]])
 }
 if(!'estimate'%in%names(z))return(data.frame())
 for(n in c('estimate','se','ci_low','ci_high')){if(!n%in%names(z))z[[n]]<-NA_real_;z[[n]]<-suppressWarnings(as.numeric(z[[n]]))}
 z$country<-toupper(sub('^iso3:','',z$country,ignore.case=TRUE));z$survey<-toupper(z$survey)
 z$domain[z$domain%in%c('math','rekenen')]<-'mathematics';z$domain[z$domain=='scie']<-'science'
 z$domain[z$domain=='read']<-'reading';z$domain[z$domain=='']<-'all'
 z$year<-suppressWarnings(as.integer(z$year));if(!'module'%in%names(z))z$module<-'';z$source_row<-z$locator_row
 z$peer_definition[z$peer_definition%in%c('none','not_applicable')]<-''
 # Already versioned V10 outputs require no semantic adaptation.
 if('contract'%in%names(z)&&all(z$contract==V10_CONTRACT)) {
  z$source_file<-normalizePath(path,winslash='/',mustWork=FALSE);z$source_fingerprint<-v10_fingerprint(path)
  z$source_script[z$source_script=='']<-script;return(z)
 }
 oldstat<-z$stat;oldgrp<-z$group;def<-z$definition
 sesdef<-ifelse(nzchar(z$ses_definition),z$ses_definition,def)
 # Verified V6 estimator aliases. Threshold 400/550 IEA statistics are deliberately
 # not aliased to the V8 475/625 statistics.
 aliases<-c(q1_prof2='q1_basic',q4_prof2='q4_basic',q1_top='q1_high',q4_top='q4_high',
             score_gap='score_gap_q4_minus_q1',gap_baseline='basic_gap_q4_minus_q1',gap_top='high_gap_q4_minus_q1')
 ai<-match(z$stat,names(aliases));okalias<-!is.na(ai)&z$survey=='PISA'&sesdef=='national_ESCS_fractional_weighted_quartiles'&z$family=='ses'
 z$stat[okalias]<-unname(aliases[ai[okalias]])
 peer<-grepl('peer_exposure',z$family)
 z$module[peer]<-z$family[peer]
 if(!'calculation_policy'%in%names(z))z$calculation_policy<-''
 z$calculation_policy[peer]<-'legacy_V8_peer_missing_and_unit_policy'
 z$group[peer&z$group=='']<-z$stat[peer&z$group=='']
 z$definition[peer]<-z$family[peer]
 z$domain[peer&!z$family%in%'high_proficiency_peer_exposure']<-'all'
 z$unit[peer]<-'percent'
 # Preserve raw/harmonized high-peer samples as different constructs.
 hp<-z$family=='high_proficiency_peer_exposure'
 z$definition[hp]<-ifelse(grepl('harmonized',z$variant[hp]),'high_peer_harmonized_sample','high_peer_raw_sample')
 sp<-z$family=='ses_peer_exposure'
 z$definition[sp]<-ifelse(z$survey[sp]=='PISA','Cobreros_fourwave_13item_trend_comparable','books5_fractional')
 # Total means and distribution.
 core<-z$group=='total'&z$stat%in%c('mean','mean_score','overall_mean','p10','p50','p90','p90_p10')&
       z$family%in%c('levels','distribution')&z$definition%in%c('total','')
 z$module[core]<-'core';z$stat[core&z$stat%in%c('mean_score','overall_mean')]<-'mean';z$definition[core]<-'total'
 # Some legacy files record total means under the one-wave SES definition.
 c2<-z$stat=='overall_mean'&z$family=='levels';z$module[c2]<-'core';z$stat[c2]<-'mean';z$group[c2]<-'total';z$definition[c2]<-'total'
 gd<-z$family=='gender'&(z$group%in%c('girl','boy')&z$stat=='mean'|z$stat%in%c('gender_girl_mean','gender_boy_mean'))
 z$module[gd]<-'gender';z$group[gd&oldstat=='gender_girl_mean']<-'girl';z$group[gd&oldstat=='gender_boy_mean']<-'boy'
 z$stat[gd]<-'mean';z$definition[gd]<-'gender'
 # Reject the known PIRLS-2021 pupil-share cells mislabeled as mean score.
 badshare<-gd&z$survey=='PIRLS'&z$year==2021&z$estimate<100&grepl('achievement-gender',z$source)
 z$module[badshare]<-''
 # Exact V8/V9 SES rows are directly reusable, including their conditional status.
 sd<-sesdef%in%c('books_at_home_5cat_fractional_quartiles','student_books_5cat_fractional_quartiles',
                'student_books5_fractional_weighted_quartiles','national_ESCS_fractional_weighted_quartiles',
                'Cobreros_fourwave_13item_trend_comparable')
 ss<-sd&z$stat%in%c('q1_mean','q4_mean','q1_basic','q4_basic','q1_high','q4_high',
                   'score_gap_q4_minus_q1','basic_gap_q4_minus_q1','high_gap_q4_minus_q1')
 z$module[ss]<-ifelse(sesdef[ss]=='Cobreros_fourwave_13item_trend_comparable','ses_harmonized','ses_national')
 z$definition[ss]<-ifelse(z$survey[ss]=='PISA',sesdef[ss],'books5_fractional')
 z$group[ss]<-ifelse(grepl('gap',z$stat[ss]),'q4_minus_q1',ifelse(grepl('^q1',z$stat[ss]),'q1','q4'))
 # The merged V8 master mislabeled Cobreros proportions as score_points.
 # Units are recovered from the exact estimator statistic names, without
 # changing a number. The source file retains the original metadata.
 z$unit[ss]<-ifelse(grepl('basic|high',z$stat[ss]),ifelse(grepl('gap',z$stat[ss]),'proportion_difference','proportion'),'score_points')
 z$threshold[ss&grepl('basic',z$stat)]<-mapply(function(s,d)thresholds_for(s,d)['basic'],z$survey[ss&grepl('basic',z$stat)],z$domain[ss&grepl('basic',z$stat)])
 z$threshold[ss&grepl('high',z$stat)]<-mapply(function(s,d)thresholds_for(s,d)['high'],z$survey[ss&grepl('high',z$stat)],z$domain[ss&grepl('high',z$stat)])
 ht<-z$stat=='total_high';z$module[ht]<-'core';z$group[ht]<-'total';z$definition[ht]<-'total'
 z$threshold[ht]<-mapply(function(s,d)thresholds_for(s,d)['high'],z$survey[ht],z$domain[ht])
 z$unit[ht]<-'proportion'
 ot<-z$survey=='PISA'&z$family=='levels'&z$group=='total'&oldstat=='top'&def=='total'&z$unit=='percent'
 z$module[ot]<-'core';z$stat[ot]<-'total_high';z$definition[ot]<-'total';z$unit[ot]<-'proportion'
 for(n in c('estimate','se','ci_low','ci_high'))z[[n]][ot]<-z[[n]][ot]/100
 z$threshold[ot]<-mapply(function(s,d)thresholds_for(s,d)['high'],z$survey[ot],z$domain[ot])
 # Retain the already-produced generation supplements. Main targets pool the
 # first and second generations; existing split results remain exportable.
 gen<-z$family=='migration_generation'&z$stat%in%c('mean_score','mean_score_gap')
 z$module[gen]<-'migration_generation';z$definition[gen]<-'pisa_both_parents_abroad_generations'
 # Explicit OECD binary aggregates: first/second are already pooled here.
 mg<-z$family=='migration'&z$definition=='immigrant_background'&z$stat=='mean'&z$group%in%c('immigrant','non_immigrant')
 z$module[mg]<-'migration';z$definition[mg]<-'pisa_both_parents_abroad'
 z$group[mg]<-ifelse(z$group[mg]=='immigrant','migration','reference')
 # Frequency means remain original categories and never become binary language.
 lg<-z$family=='language'&z$stat=='mean'&z$group%in%c('always','almost','almost_always','sometimes','never')
 z$module[lg]<-'language_frequency';z$definition[lg]<-'assessment_language_frequency';z$group[lg&z$group=='almost']<-'almost_always'
 lb<-z$family=='language'&z$stat=='mean'&z$group%in%c('always_almost','sometimes_never')
 z$module[lb]<-'language_frequency_binary';z$definition[lb]<-'frequency_always_almost_vs_sometimes_never'
 el<-z$family=='home_language'&z$stat%in%c('mean_score','mean_score_gap')
 z$module[el]<-'language_exact';z$definition[el]<-'same_as_assessment_language_vs_other';z$stat[el&oldstat=='mean_score']<-'mean'
 z$stat[el&oldstat=='mean_score_gap']<-'gap';z$group[el&oldstat=='mean_score_gap']<-'other_minus_test'
 # Legacy official national SES is kept as its own construct. The requirement
 # selector below can reuse it for a slide already using that construct.
 off<-z$family=='ses'&def=='national_ESCS'&oldgrp%in%c('q1','q4')&oldstat%in%c('mean','low','top')
 z$module[off]<-'ses_national';z$definition[off]<-'national_ESCS_official_quartiles'
 for(g in c('q1','q4')) {
  ix<-off&oldgrp==g
  z$stat[ix]<-paste0(g,'_',ifelse(oldstat[ix]=='mean','mean',ifelse(oldstat[ix]=='low','basic','high')))
 }
 rate<-off&oldstat%in%c('low','top');lo<-off&oldstat=='low'
 z$estimate[rate]<-z$estimate[rate]/100;z$se[rate]<-z$se[rate]/100
 z$ci_low[rate]<-z$ci_low[rate]/100;z$ci_high[rate]<-z$ci_high[rate]/100
 z$estimate[lo]<-1-z$estimate[lo];oldlo<-z$ci_low[lo];z$ci_low[lo]<-1-z$ci_high[lo];z$ci_high[lo]<-1-oldlo
 z$unit[rate]<-'proportion'
 z$threshold[off&oldstat=='low']<-mapply(function(s,d)thresholds_for(s,d)['basic'],z$survey[off&oldstat=='low'],z$domain[off&oldstat=='low'])
 z$threshold[off&oldstat=='top']<-mapply(function(s,d)thresholds_for(s,d)['high'],z$survey[off&oldstat=='top'],z$domain[off&oldstat=='top'])
 offgap<-z$family=='ses'&def=='national_ESCS'&oldgrp=='q4_minus_q1'&oldstat=='mean'
 z$module[offgap]<-'ses_national';z$definition[offgap]<-'national_ESCS_official_quartiles';z$stat[offgap]<-'score_gap_q4_minus_q1'
 z$source_file<-normalizePath(path,winslash='/',mustWork=FALSE);z$source_script<-script
 hasedition<-if('edition'%in%names(z))v10_text(z$edition) else rep('',nrow(z))
 z$source_script[script=='unknown'&nzchar(hasedition)]<-hasedition[script=='unknown'&nzchar(hasedition)]
 z$source_fingerprint<-v10_fingerprint(path);z$priority<-priority
 # Prefer curated released values, then matched microdata, then sensitivity files.
 z$priority[z$variant=='official']<-10L;z$priority[grepl('sensitivity',z$variant)]<-90L
 z$threshold<-v10_text(z$threshold)
 pctile<-z$module=='core'&z$stat%in%c('p10','p50','p90','p90_p10')
 z$calculation_policy[pctile]<-ifelse(z$variant[pctile]=='official','official_percentile','legacy_source_percentile')
 z$contract<-V10_CONTRACT;z$metric_key<-v10_key(z)
 z$availability<-ifelse(is.finite(z$estimate),'AVAILABLE_POINT','INVALID')
 z$uncertainty_status<-ifelse(is.finite(z$se)&z$se>=0,'SE_AVAILABLE','SE_MISSING')
 z<-z[z$module!=''&grepl('^[A-Z]{3}$',z$country)&z$survey%in%c('PISA','PIRLS','TIMSS')&!is.na(z$year),,drop=FALSE]
 # Keep a compact, stable data contract instead of repeatedly copying all the
 # old master annotations. Original annotations remain at source_file/source_row.
 keep<-c('country','survey','year','domain','module','stat','group','definition','peer_definition',
  'threshold','unit','estimate','se','ci_low','ci_high','variant','status','source','source_row',
  'source_file','source_script','source_fingerprint','priority','contract','metric_key','availability','uncertainty_status','calculation_policy')
 z<-z[keep]
 z
}
v10_reuse_existing_constructs <- function(req,catalogue) {
 # Choose an explicitly recorded official national quartile definition for
 # cells that already exist. Do not call it the fractional or harmonized method.
 good<-catalogue[catalogue$availability=='AVAILABLE_POINT'&catalogue$definition=='national_ESCS_official_quartiles',,drop=FALSE]
 for(i in which(req$module=='ses_national'&req$survey=='PISA')) {
  q<-req[i,,drop=FALSE];q$definition<-'national_ESCS_official_quartiles';key<-v10_key(q)
  if(key%in%good$metric_key){req$definition[i]<-q$definition;req$metric_key[i]<-key}
 }
 # Keep the policy of an existing figure. New corrected peer estimates/quantile
 # calculations have different keys and cannot enter the same reference mean.
 cc<-catalogue[catalogue$availability=='AVAILABLE_POINT',,drop=FALSE]
 if(nrow(cc)) {
  rr<-req;rr$calculation_policy<-'';ss<-cc;ss$calculation_policy<-''
  cc$base_key<-v10_key(ss);base<-v10_key(rr)
  for(i in which(nzchar(req$calculation_policy))) {
   k<-match(base[i],cc$base_key)
   if(!is.na(k)){req$calculation_policy[i]<-cc$calculation_policy[k];req$metric_key[i]<-v10_key(req[i,,drop=FALSE])}
  }
 }
 req
}
v10_resolve <- function(z) {
 if(!nrow(z))return(z)
 z<-z[is.finite(z$estimate)&!z$status%in%c('HELD','UNAVAILABLE','rejected'),,drop=FALSE]
 if(!nrow(z))return(z)
 out<-lapply(split(seq_len(nrow(z)),z$metric_key),function(ix){
  q<-z[ix,,drop=FALSE];q<-q[q$priority==min(q$priority),,drop=FALSE]
  # Equivalent duplicates need no new microdata. A conflicting top-priority pair
  # is explicitly held; no averaging or latest-file winner.
  conflict<-any(q$availability=='CONFLICT')||max(q$estimate)-min(q$estimate)>1e-8
  q<-q[order(!is.finite(q$se),q$source_file,q$source_row),,drop=FALSE]
  r<-q[1,,drop=FALSE];r$availability<-if(conflict)'CONFLICT' else 'AVAILABLE_POINT'
  r$candidate_count<-length(ix);r$alternative_sources<-paste(unique(z$source_file[ix]),collapse=';');r
 })
 v10_bind(out)
}

# Requirements refer to the latest 21-slide deck. Keys contain constructs,
# thresholds and peer units so a matching number with another definition cannot
# suppress a calculation. Older PISA waves have core/gender/demographic targets;
# trend-comparable SES is restricted to 2015/18/22/25.
v10_requirements <- function(countries,surveys=c('PIRLS','TIMSS','PISA'),years=NULL) {
 out<-list()
 add<-function(cc,s,y,d,m,st,g,def,slides,peer='',th='',unit='score_points') {
  out[[length(out)+1L]]<<-data.frame(country=cc,survey=s,year=y,domain=d,module=m,stat=st,group=g,
   definition=def,peer_definition=peer,threshold=v10_text(th),unit=unit,slides=slides,stringsAsFactors=FALSE)
 }
 for(cc in countries)for(s in surveys) {
  yy<-if(!is.null(years)&&!is.null(years[[s]]))years[[s]] else switch(s,PIRLS=c(2001,2006,2011,2016,2021),TIMSS=c(2003,2007,2011,2015,2019,2023),PISA=c(2003,2006,2009,2012,2015,2018,2022,2025))
  dd<-switch(s,PIRLS='reading',TIMSS=c('mathematics','science'),PISA=c('reading','mathematics','science'))
  for(y in yy) {
   # PISA science scale has no comparable 2003 target.
   ds<-if(s=='PISA'&&y==2003)setdiff(dd,'science') else dd
   for(d in ds) {
    for(st in c('mean','p10','p50','p90','p90_p10'))add(cc,s,y,d,'core',st,'total','total',if(st=='mean')'2' else '3')
    add(cc,s,y,d,'core','total_high','total','total','10;20',th=thresholds_for(s,d)['high'],unit='proportion')
    for(g in c('girl','boy'))add(cc,s,y,d,'gender','mean',g,'gender','11')
    for(def in c('pisa_both_parents_abroad','nl_one_parent_abroad')) {
     for(g in c('reference','migration'))add(cc,s,y,d,'migration','mean',g,def,'13;14')
     add(cc,s,y,d,'migration','gap','migration_minus_reference',def,'15')
    }
    if(s=='PISA') {
     for(g in c('test_language_home','other_language_home'))add(cc,s,y,d,'language_exact','mean',g,'same_as_assessment_language_vs_other','12')
     add(cc,s,y,d,'language_exact','gap','other_minus_test','same_as_assessment_language_vs_other','12')
    } else if(s=='PIRLS') {
     for(g in c('always_almost','sometimes_never'))add(cc,s,y,d,'language_frequency_binary','mean',g,'frequency_always_almost_vs_sometimes_never','12')
    } else {
     for(g in c('always','almost_always','sometimes','never'))add(cc,s,y,d,'language_frequency','mean',g,'assessment_language_frequency','12')
     for(g in c('always_almost','sometimes_never'))add(cc,s,y,d,'language_frequency_binary','mean',g,'frequency_always_almost_vs_sometimes_never','12')
    }
    for(m in c('ses_national',if(s=='PISA'&&y>=2015)'ses_harmonized')) {
     def<-if(s!='PISA')'books5_fractional' else if(m=='ses_harmonized')'Cobreros_fourwave_13item_trend_comparable' else 'national_ESCS_fractional_weighted_quartiles'
     for(st in c('q1_mean','q4_mean','q1_basic','q4_basic','q1_high','q4_high','score_gap_q4_minus_q1','basic_gap_q4_minus_q1','high_gap_q4_minus_q1')) {
      th<-if(grepl('basic',st))thresholds_for(s,d)['basic'] else if(grepl('high',st))thresholds_for(s,d)['high'] else ''
      unit<-if(grepl('basic|high',st))if(grepl('gap',st))'proportion_difference' else 'proportion' else 'score_points'
      g<-if(grepl('gap',st))'q4_minus_q1' else if(grepl('^q1',st))'q1' else 'q4'
      add(cc,s,y,d,m,st,g,def,if(m=='ses_harmonized')'7;8;9;10' else '4;5;6;10',th=th,unit=unit)
     }
    }
    for(pd in c('direct_learning_environment','whole_school')) {
     for(g in c('self_below_high','self_high'))add(cc,s,y,d,'high_proficiency_peer_exposure',g,g,'high_peer_raw_sample','20',pd,thresholds_for(s,d)['high'],'percent')
     add(cc,s,y,d,'peer_baseline','high_share','total','high_peer_raw_sample','20',pd,thresholds_for(s,d)['high'],'percent')
    }
   }
   for(pd in c('direct_learning_environment','whole_school')) {
    if(s!='PISA'||y>=2015)for(st in c('q1_target_pct_q4_peers','q4_target_pct_q1_peers'))
     add(cc,s,y,'all','ses_peer_exposure',st,st,if(s=='PISA')'Cobreros_fourwave_13item_trend_comparable' else 'books5_fractional','16;17',pd,unit='percent')
    if(s!='PISA'||y>=2015)for(st in c('q1_share','q4_share'))add(cc,s,y,'all','peer_baseline',st,'total',if(s=='PISA')'Cobreros_fourwave_13item_trend_comparable' else 'weighted_SES_quartile_share','16;17',pd,unit='percent')
    if(s=='PISA') {
     add(cc,s,y,'all','home_language_peer_exposure','other_language_target_pct_test_language_home_peers','other_language_target_pct_test_language_home_peers','home_language_peer_exposure','18',pd,unit='percent')
     add(cc,s,y,'all','peer_baseline','test_language_share','total','same_as_assessment_language_vs_other','18',pd,unit='percent')
    } else {
     add(cc,s,y,'all','home_language_frequency_peer','less_often_target_pct_always_almost_peers','less_often','frequency_always_almost_vs_sometimes_never','18',pd,unit='percent')
     add(cc,s,y,'all','peer_baseline','test_language_share','total','frequency_always_almost_vs_sometimes_never','18',pd,unit='percent')
    }
    for(def in c('pisa_both_parents_abroad','nl_one_parent_abroad')) {
     add(cc,s,y,'all','migration_binary_peer','migration_target_pct_reference_peers','migration',def,'19',pd,unit='percent')
     add(cc,s,y,'all','peer_baseline','reference_share','total',def,'19',pd,unit='percent')
    }
   }
  }
 }
 z<-v10_bind(out);z$calculation_policy<-ifelse(z$peer_definition!='','V10_exclude_unknown_peer_status_and_singletons','')
 z$calculation_policy[z$module=='core'&z$stat%in%c('p10','p50','p90','p90_p10')]<-'weighted_empirical_step_quantile'
 z$calculation_policy[z$module=='peer_baseline']<-'population_share'
 # The SES exposure backend is unchanged and uses fractional/replicate tails.
 z$calculation_policy[z$module=='ses_peer_exposure']<-'legacy_V8_peer_missing_and_unit_policy'
 z$metric_key<-v10_key(z);z
}

# Source discovery lists file names only. No survey import or RDS pupil reading.
v10_sources <- function(root,downloads,base) {
 dirs<-unique(c(getOption('pisa.fast.result_dirs',character()),root,downloads))
 pat<-'(MASTER|FINAL_PRODUCT_BASIS|TASK_RESULTS|NEW_MASTER_ROWS|NEW_OR_RECALCULATED|GETOONDE_RECORDS|RESULTS_CANONICAL|RESULTS_FOR_DASHBOARD|NLD_REEDS_GEPRODUCEERD).*\\.csv(\\.gz)?$'
 ff<-getOption('pisa.fast.result_files',character())
 for(d in dirs[dir.exists(dirs)]) {
  if(identical(normalizePath(d,winslash='/'),normalizePath(downloads,winslash='/')))ff<-c(ff,list.files(d,pattern=pat,full.names=TRUE,ignore.case=TRUE))
  else for(k in 0:5)ff<-c(ff,Sys.glob(file.path(d,paste(rep('*',k),collapse='/'),'*.csv')),Sys.glob(file.path(d,paste(rep('*',k),collapse='/'),'*.csv.gz')))
 }
 master<-getOption('pisa.fast.master','');if(nzchar(master))ff<-c(ff,master)
 ff<-unique(ff[file.exists(ff)]);ff<-ff[grepl(pat,basename(ff),ignore.case=TRUE)|ff%in%getOption('pisa.fast.result_files',character())|ff==master]
 ff<-ff[!startsWith(normalizePath(ff,winslash='/',mustWork=FALSE),paste0(normalizePath(base,winslash='/',mustWork=FALSE),'/'))]
 # Recover only result CSVs from known handoff/run archives. No student extraction.
 zz<-unique(c(getOption('pisa.fast.result_archives',character()),list.files(downloads,pattern='^(PISA_V8_AFGEROND|OVERDRACHT_PROJECTPRODUCTEN|run_[0-9]|PISA_SLIDES_DASHBOARD_CONTROLE).*\\.zip$',full.names=TRUE)))
 for(p in zz[file.exists(zz)]) {
  members<-tryCatch(unzip(p,list=TRUE)$Name,error=function(e)character())
  members<-members[grepl(pat,basename(members),ignore.case=TRUE)&!grepl('(^[/\\\\]|^[A-Za-z]:|(^|/)\\.\\.(/|$))',members)]
  dest<-file.path(base,'imports',unname(tools::md5sum(p)))
  for(m in members){q<-file.path(dest,m);if(!file.exists(q)){dir.create(dest,recursive=TRUE,showWarnings=FALSE);unzip(p,files=m,exdir=dest)};if(file.exists(q))ff<-c(ff,q)}
 }
 unique(ff)
}

v10_import <- function(files,registry_dir) {
 si_path<-file.path(registry_dir,'SOURCE_INVENTORY.csv');si<-v10_read(si_path)
 rows<-list();inv<-list()
 for(p in files) {
  p<-normalizePath(p,winslash='/',mustWork=TRUE);fp<-v10_fingerprint(p)
  t<-tempfile();writeLines(p,t);id<-unname(tools::md5sum(t));unlink(t)
  cache<-file.path(registry_dir,'source_rows',paste0(id,'.rds'))
  k<-if(nrow(si))match(p,si$source_file) else NA_integer_
  cached<-if(!is.na(k)&&si$fingerprint[k]==fp&&file.exists(cache))tryCatch(readRDS(cache),error=function(e)NULL) else NULL
  if(!is.null(cached)) {
   z<-cached;record<-si[k,,drop=FALSE]
  } else {
   x<-tryCatch(v10_read(p),error=function(e)e)
   if(inherits(x,'error')) {
    z<-data.frame();record<-data.frame(source_file=p,fingerprint=fp,md5=NA,rows=0,adopted=0,source_script='unknown',status='READ_ERROR',message=conditionMessage(x))
   } else {
    script<-if(grepl('v8|26_dashboard',p,ignore.case=TRUE))'V8_20260930' else if(grepl('v9|27_dashboard',p,ignore.case=TRUE))'V9_20260930' else 'unknown'
    z<-v10_adapt(x,p,script);record<-data.frame(source_file=p,fingerprint=fp,md5=unname(tools::md5sum(p)),rows=nrow(x),adopted=nrow(z),source_script=script,status='INDEXED',message='')
   }
   v10_save_rds(z,cache)
  }
  rows[[length(rows)+1L]]<-z;inv[[length(inv)+1L]]<-record
 }
 v10_write(v10_bind(inv),si_path);v10_bind(rows)
}

# Backend is loaded only when a missing target needs microdata. Pure reuse and
# comparator-only runs do not require the old engine, arrow, Rcpp, Git or raw data.
v10_init_backend <- function() {
 if(isTRUE(V10_BACKEND_READY))return(invisible(NULL))
 ENGINE<<-find_engine();logmsg('Engine: ',ENGINE)
 options(pisa.completion.functions_only=TRUE)
 keep<-mget(c('ROOT','DOWNLOADS','BASE','CACHE','TASK_DIR','STATE_DIR','OUT','LOG'),envir=.GlobalEnv)
 source(ENGINE,local=.GlobalEnv);list2env(keep,envir=.GlobalEnv)
 # Restore the V9 helper overrides, including the safe one-statistic PV wrapper.
 rc2_pool_engine_v8<<-rc2_pool
 eval(parse(text=V10_BACKEND_FUNCTIONS),envir=.GlobalEnv)
 bind_safe<<-v10_bind;atomic_write_csv<<-v10_write;write_csv<<-v10_write
 ensure_packages('data.table')
 if(exists('rc2_fast_state',inherits=FALSE))rc2_fast_state$watch<-FALSE
 FAST_SOURCE_DIRS<<-unique(c(getOption('pisa.fast.source_dirs',character()),DOWNLOADS,
  file.path(ROOT,c('21_completion_repair_v7/sources','22_completion_final_v8/sources','20_rc2_domains/sources',
                   '23_slide_only_completion/cache/sources','23_slide_only_completion/cache/extracts'))))
 FAST_SOURCE_DIRS<<-FAST_SOURCE_DIRS[dir.exists(FAST_SOURCE_DIRS)];INV<<-fast_inventory()
 # Include unpacked files one folder below Downloads and known project sources.
 exact<-c('CY6_MS_CMB_STU_QQQ.sav','CY07_MSU_STU_QQQ.sav','CY08MSP_STU_QQQ.sav','CY09_MS_STU_PUF.sav')
 ff<-unique(c(unlist(lapply(list.dirs(DOWNLOADS,recursive=FALSE),function(d)list.files(d,full.names=TRUE))),
  unlist(lapply(0:4,function(k)Sys.glob(file.path(ROOT,paste(rep('*',k),collapse='/'),'*.sav'))))))
 ff<-ff[basename(ff)%in%exact&file.exists(ff)]
 if(length(ff))INV<<-unique(rbind(INV,data.frame(path=norm(ff),basename=basename(ff),bytes=file.info(ff)$size,extension='sav')))
 roots<-file.path(ROOT,c('26_dashboard_fast_resumable/cache','27_dashboard_multicountry_v9/cache',
  '23_slide_only_completion/cache','22_completion_final_v8/cache','20_rc2_domains/cache','21_completion_repair_v7/cache'))
 RDS_FILES<<-unique(c(list.files(CACHE,pattern='\\.rds$',recursive=TRUE,full.names=TRUE),
  unlist(lapply(roots[dir.exists(roots)],list.files,pattern='\\.rds$',recursive=TRUE,full.names=TRUE))))
 RDS_NLD<<-RDS_FILES
 v11_install_raw_mapper()
 v11_install_cache_guard()
 V10_BACKEND_READY<<-TRUE
}

v10_pool <- function(obj,fn) {
 des<-rc2_replicate_design(obj$data,obj$meta$survey,obj$meta$year)
 full<-as.matrix(fn(des$w));rr<-array(NA_real_,c(des$n,nrow(full),ncol(full)))
 for(r in seq_len(des$n))rr[r,,]<-fn(rc2_repweight(des,r))
 rc2_pool(full,rr,des$factor)
}
v10_weighted_quantile <- function(y,w,p) {
 ok<-is.finite(y)&is.finite(w)&w>0;if(!any(ok))return(rep(NA_real_,length(p)))
 o<-order(y[ok]);yy<-y[ok][o];ww<-w[ok][o];cw<-cumsum(ww)/sum(ww)
 vapply(p,function(q)yy[which(cw>=q)[1]],numeric(1))
}
v10_gender <- function(obj) {
 d<-obj$data
 for(n in c('DEMO_GENDER','GENDER','SEX'))if(n%in%names(d)) {
  x<-tolower(v10_text(d[[n]]));g<-rep(NA_character_,length(x));g[x%in%c('girl','female','meisje','1')]<-'girl';g[x%in%c('boy','male','jongen','2')]<-'boy'
  # Numeric codes are accepted only for an engine canonical GENDER/DEMO_GENDER.
  if(n=='SEX'&&any(x%in%c('1','2')))next
  if(any(!is.na(g)))return(g)
 }
 stop('Geen gecontroleerde canonical gender-indeling.')
}
v10_migration <- function(obj,definition) {
 d<-obj$data
 # A caller may supply verified harmonised vectors without changing this script.
 hook<-getOption('pisa.fast.birthplace_mapper',NULL)
 if(is.function(hook))b<-hook(obj) else b<-NULL
 if(is.null(b)&&all(c('MOTHER_BORN_HERE','FATHER_BORN_HERE')%in%names(d)))b<-list(mother=d$MOTHER_BORN_HERE,father=d$FATHER_BORN_HERE)
 if(!is.null(b)) {
  if(!is.logical(b$mother)||!is.logical(b$father)||length(b$mother)!=nrow(d)||length(b$father)!=nrow(d))stop('Birthplace mapper moet twee logische vectoren leveren (NA onbekend).')
  migrant<-if(definition=='nl_one_parent_abroad')!b$mother|!b$father else !b$mother&!b$father
  return(ifelse(is.na(migrant),NA_character_,ifelse(migrant,'migration','reference')))
 }
 if(definition=='nl_one_parent_abroad')stop('Nederlandse ouderdefinitie vereist gecontroleerde oudergeboorteplaatsen; IMMIG is onvoldoende.')
 g<-v10_text(d$DEMO_MIGRATION)
 if(length(g)!=nrow(d)||!any(g%in%c('native','first_generation','second_generation')))stop('Geen gecontroleerde migratieconstructie.')
 ifelse(g=='native','reference',ifelse(g%in%c('first_generation','second_generation'),'migration',NA_character_))
}
v10_language_legacy <- function(obj,frequency=FALSE) {
 g<-tolower(v10_text(obj$data$DEMO_LANGUAGE));g[g=='almost']<-'almost_always'
 if(length(g)!=nrow(obj$data))stop('Geen thuistaalconstructie.')
 if(frequency) {
  g[!g%in%c('always','almost_always','sometimes','never')]<-NA_character_
  if(!any(!is.na(g)))stop('Geen gecontroleerde oorspronkelijke taal-frequentiecategorieën.');return(g)
 }
 L<-language_groups(obj);if(!isTRUE(L$ok))stop(L$reason);L$group
}

# Peer denominator excludes unclassified pupils and singleton units. Existing
# V8/V9 estimates remain retained and conditional; changed policy has its own note.
v10_peer <- function(unit,g,positive,target,w) {
 ok<-!is.na(unit)&nzchar(v10_text(unit))&!is.na(g)&is.finite(w)&w>0
 if(!any(ok))return(NA_real_)
 u<-as.character(unit[ok]);ww<-w[ok];gg<-g[ok]
 tw<-ave(ww,u,FUN=sum);pw<-ave(ww*as.numeric(gg==positive),u,FUN=sum)
 den<-tw-ww;share<-(pw-ww*as.numeric(gg==positive))/den
 weighted_mean(share,ww*as.numeric(gg==target))
}
v10_peer_matrix <- function(unit,peer,target,W) {
 ok<-!is.na(unit)&nzchar(v10_text(unit))&is.finite(peer)&is.finite(target)
 if(!any(ok))return(rep(NA_real_,ncol(W)))
 u<-as.character(unit[ok]);gid<-match(u,unique(u));ww<-W[ok,,drop=FALSE];p<-peer[ok];t<-target[ok]
 total<-rowsum(ww,gid,reorder=TRUE);numer<-rowsum(ww*p,gid,reorder=TRUE)
 share<-(numer[gid,,drop=FALSE]-ww*p)/(total[gid,,drop=FALSE]-ww)
 good<-is.finite(share);tw<-ww*t;den<-colSums(ifelse(good,tw,0));num<-colSums(ifelse(good,tw*share,0))
 out<-num/den;out[!is.finite(out)]<-NA_real_;out
}
v10_fast_high_peer <- function(obj,q) {
 d<-obj$data;des<-rc2_replicate_design(d,obj$meta$survey,obj$meta$year)
 W<-cbind(des$w,vapply(seq_len(des$n),function(r)rc2_repweight(des,r),numeric(nrow(d))))
 pp<-pv_names(d,q$domain[1]);if(!length(pp))stop('PVs ontbreken.')
 unit<-unit_for(obj,q$peer_definition[1]);f<-matrix(NA_real_,length(pp),nrow(q));colnames(f)<-q$stat
 rr<-array(NA_real_,c(des$n,length(pp),nrow(q)))
 for(m in seq_along(pp)) {
  y<-rc2_num(d[[pp[m]]]);hi<-ifelse(is.finite(y),as.numeric(y>=as.numeric(q$threshold[1])),NA_real_)
  for(k in seq_len(nrow(q))) {
   target<-if(q$group[k]=='self_high')hi else 1-hi
   e<-100*v10_peer_matrix(unit,hi,target,W);f[m,k]<-e[1];rr[,m,k]<-e[-1]
  }
 }
 po<-rc2_pool(f,rr,des$factor);q$estimate<-as.numeric(po$estimate);q$se<-as.numeric(po$se)
 q$ci_low<-q$estimate-1.96*q$se;q$ci_high<-q$estimate+1.96*q$se;q
}
v10_cobreros_quartile_baseline <- function(g,q) {
 repo<-file.path(DOWNLOADS,'pisa_2025_cobreros');Sys.setenv(PISA_REPO=repo)
 AE<-new.env(parent=.GlobalEnv);sys.source(file.path(repo,'code/r/R/core.R'),envir=AE)
 g<-data.table::as.data.table(g);W<-AE$weights_for(g);codes<-v8_quantile_codes(AE,g$escs_h4,W)
 for(k in seq_len(nrow(q))) {
  target<-if(q$stat[k]=='q1_share')0 else 3
  e<-vapply(seq_len(ncol(W)),function(j)100*weighted_mean(as.numeric(codes[,j]==target),W[,j]),numeric(1))
  q$estimate[k]<-e[1];q$se[k]<-sqrt(sum((e[-1]-e[1])^2)/(80*.25))
 }
 q$ci_low<-q$estimate-1.96*q$se;q$ci_high<-q$estimate+1.96*q$se;q
}

v10_compute <- function(obj,q) {
 if(!nrow(q))return(q)
 d<-obj$data;m<-q$module[1];domain<-q$domain[1];def<-q$definition[1]
 # SES backend already estimates all contrasts with PV/replicate covariance.
 if(m=='high_proficiency_peer_exposure')return(v10_fast_high_peer(obj,q))
 if(m=='ses_national') {
  pp<-pv_names(d,domain);if(!length(pp))stop('PVs ontbreken.')
  one<-function(w) {
   tails<-rc2_tails_rank(d$SES,w);z<-matrix(NA_real_,length(pp),nrow(q));colnames(z)<-q$stat
   for(j in seq_along(pp)) {
    y<-rc2_num(d[[pp[j]]]);b<-as.numeric(y>=thresholds_for(obj$meta$survey,domain)['basic']);h<-as.numeric(y>=thresholds_for(obj$meta$survey,domain)['high'])
    vals<-c(q1_mean=weighted_mean(y,w*tails$q1),q4_mean=weighted_mean(y,w*tails$q4),
     q1_basic=weighted_mean(b,w*tails$q1),q4_basic=weighted_mean(b,w*tails$q4),q1_high=weighted_mean(h,w*tails$q1),q4_high=weighted_mean(h,w*tails$q4))
    vals<-c(vals,score_gap_q4_minus_q1=unname(vals['q4_mean']-vals['q1_mean']),basic_gap_q4_minus_q1=unname(vals['q4_basic']-vals['q1_basic']),high_gap_q4_minus_q1=unname(vals['q4_high']-vals['q1_high']))
    z[j,]<-vals[q$stat]
   };z
  }
 } else {
  g<-NULL;unit<-NULL
  if(m=='gender')g<-v10_gender(obj)
  if(m%in%c('migration','migration_binary_peer')||(m=='peer_baseline'&&q$stat[1]=='reference_share'))g<-v10_migration(obj,def)
  if(m=='language_exact'||m=='home_language_peer_exposure'||m=='peer_baseline'&&def=='same_as_assessment_language_vs_other')g<-v10_language(obj)
  if(m%in%c('language_frequency','language_frequency_binary','home_language_frequency_peer')||m=='peer_baseline'&&def=='frequency_always_almost_vs_sometimes_never') {
   g<-v10_language(obj,TRUE)
   if(m=='language_frequency'&&any(g=='always_or_almost_always',na.rm=TRUE))stop('BLOCKED_MAPPING: bron combineert always/almost; vier categorieen niet identificeerbaar. Gebruik de afzonderlijke binaire frequentie-uitkomsten.')
   if(m=='language_frequency_binary')g<-ifelse(is.na(g),NA_character_,ifelse(g%in%c('always','almost_always','always_or_almost_always'),'always_almost','sometimes_never'))
   else if(m!='language_frequency')g<-ifelse(is.na(g),NA_character_,ifelse(g%in%c('always','almost_always','always_or_almost_always'),'test_language_home','other_language_home'))
  }
  peer<-q$peer_definition[1]!='';if(peer)unit<-unit_for(obj,q$peer_definition[1])
  fixed<-domain=='all';pp<-if(fixed)'__fixed__' else pv_names(d,domain)
  if(!length(pp))stop('Geen plausible values voor ',domain)
  one<-function(w) {
   z<-matrix(NA_real_,length(pp),nrow(q));colnames(z)<-paste(q$stat,q$group,sep='::')
   for(j in seq_along(pp)) {
    y<-if(fixed)rep(1,nrow(d)) else rc2_num(d[[pp[j]]])
    for(k in seq_len(nrow(q))) {
     st<-q$stat[k];gr<-q$group[k]
     z[j,k]<-switch(m,
      core=switch(st,mean=weighted_mean(y,w),p10=v10_weighted_quantile(y,w,.1),p50=v10_weighted_quantile(y,w,.5),p90=v10_weighted_quantile(y,w,.9),p90_p10=diff(v10_weighted_quantile(y,w,c(.1,.9))),total_high=weighted_mean(as.numeric(y>=as.numeric(q$threshold[k])),w),stop('Unknown core stat')),
      gender=weighted_mean(y,w*as.numeric(g==gr)),
      migration=if(st=='gap')weighted_mean(y,w*as.numeric(g=='migration'))-weighted_mean(y,w*as.numeric(g=='reference')) else weighted_mean(y,w*as.numeric(g==gr)),
      language_frequency=weighted_mean(y,w*as.numeric(g==gr)),
      language_frequency_binary=weighted_mean(y,w*as.numeric(g==gr)),
      language_exact=if(st=='gap')weighted_mean(y,w*as.numeric(g=='other_language_home'))-weighted_mean(y,w*as.numeric(g=='test_language_home')) else weighted_mean(y,w*as.numeric(g==gr)),
      migration_binary_peer=v10_peer(unit,g,'reference','migration',w),
      home_language_peer_exposure=v10_peer(unit,g,'test_language_home','other_language_home',w),
      home_language_frequency_peer=v10_peer(unit,g,'test_language_home','other_language_home',w),
      ses_peer_exposure={tails<-rc2_tails_rank(d$SES,w);if(st=='q1_target_pct_q4_peers')100*peer_share(unit,tails$q4,tails$q1,w) else 100*peer_share(unit,tails$q1,tails$q4,w)},
      high_proficiency_peer_exposure={hi<-ifelse(is.finite(y),ifelse(y>=as.numeric(q$threshold[k]),'high','low'),NA_character_);v10_peer(unit,hi,'high',if(gr=='self_high')'high' else 'low',w)},
      peer_baseline=switch(st,
       high_share=100*weighted_mean(as.numeric(y>=as.numeric(q$threshold[k])),w),
       reference_share=100*weighted_mean(as.numeric(g=='reference'),w),
       test_language_share=100*weighted_mean(as.numeric(g=='test_language_home'),w),
       q1_share={t<-rc2_tails_rank(d$SES,w);100*weighted_mean(t$q1,w)},
       q4_share={t<-rc2_tails_rank(d$SES,w);100*weighted_mean(t$q4,w)},stop('Unknown baseline')),
      stop('Unknown module: ',m))
     if(m%in%c('migration_binary_peer','home_language_peer_exposure','home_language_frequency_peer','high_proficiency_peer_exposure'))z[j,k]<-100*z[j,k]
    }
   };z
  }
 }
 po<-v10_pool(obj,one);out<-q;out$estimate<-as.numeric(po$estimate);out$se<-as.numeric(po$se)
 out$ci_low<-out$estimate-1.96*out$se;out$ci_high<-out$estimate+1.96*out$se;out
}

v10_reference <- function(z,requirements,pool=setdiff(v10_codes(COMMON42),'NLD')) {
 rows<-list();members<-list();holds<-list()
 if(!nrow(z))return(list(results=data.frame(),members=data.frame(),holds=data.frame()))
 templates<-requirements;templates$series<-v10_key(templates,FALSE);templates<-templates[!duplicated(templates$series),,drop=FALSE]
 z$series<-v10_key(z,FALSE)
 for(i in seq_len(nrow(templates))) {
  t<-templates[i,,drop=FALSE];q<-z[z$series==t$series&z$country%in%pool&z$availability=='AVAILABLE_POINT',,drop=FALSE]
  missing<-setdiff(pool,q$country)
  if(length(missing)||anyDuplicated(q$country)) {
   h<-t;h$expected_n<-length(pool);h$observed_n<-length(unique(q$country));h$missing_countries<-paste(missing,collapse=';');h$reason<-'Fixed pool incomplete or duplicate';holds[[length(holds)+1L]]<-h
   if(!nrow(q)||anyDuplicated(q$country)||identical(getOption('pisa.fast.reference_policy','available'),'strict'))next
  }
  t$country<-'REF_COMMON41';t$estimate<-mean(q$estimate);t$comparator_n<-nrow(q)
  t$expected_n<-length(pool);t$membership_status<-if(length(missing))'INCOMPLETE_POOL' else 'COMPLETE_POOL'
  t$missing_countries<-paste(missing,collapse=';')
  allse<-all(is.finite(q$se)&q$se>=0);t$se<-if(allse)sqrt(sum(q$se^2))/nrow(q) else NA_real_
  t$ci_low<-t$estimate-1.96*t$se;t$ci_high<-t$estimate+1.96*t$se
  t$method<-'Arithmetic mean of country estimates; equal country weights; NL excluded'
  t$uncertainty_method<-if(allse)'Independent country samples: sqrt(sum(SE^2))/N' else 'Missing country SE: point estimate only'
  rows[[length(rows)+1L]]<-t;q$comparator_key<-t$series;members[[length(members)+1L]]<-q
 }
 list(results=v10_bind(rows),members=v10_bind(members),holds=v10_bind(holds))
}
v10_aggregate_derivatives <- function(catalogue,requirements) {
 out<-list()
 requirements<-requirements[!duplicated(v10_key(requirements,FALSE)),,drop=FALSE]
 for(i in which(requirements$module=='peer_baseline'&requirements$stat=='high_share')) {
  q<-requirements[i,,drop=FALSE]
  k<-catalogue$survey==q$survey&catalogue$year==q$year&catalogue$domain==q$domain&
     catalogue$module=='core'&catalogue$stat=='total_high'&catalogue$threshold==q$threshold&catalogue$availability=='AVAILABLE_POINT'
  zz<-catalogue[k,,drop=FALSE];if(!nrow(zz))next
  for(j in seq_len(nrow(zz))) {
   z<-zz[j,,drop=FALSE];r<-q;r$country<-z$country;r$metric_key<-v10_key(r)
   if(any(catalogue$metric_key==r$metric_key&catalogue$availability=='AVAILABLE_POINT'))next
   for(n in c('estimate','se','ci_low','ci_high'))r[[n]]<-100*z[[n]]
   r$source_file<-z$source_file;r$source_row<-z$source_row;r$source_script<-z$source_script
   r$source_fingerprint<-z$source_fingerprint;r$priority<-z$priority;r$status<-z$status
   r$availability<-'AVAILABLE_POINT';r$contract<-V10_CONTRACT;r$uncertainty_status<-z$uncertainty_status
   r$derivation<-'100 * existing total-high proportion; no new pupil calculation'
   out[[length(out)+1L]]<-r
  }
 }
 v10_bind(out)
}

v10_execute <- function() {
 options(stringsAsFactors=FALSE,digits=17)
 Sys.setenv(OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1')
 if(requireNamespace('data.table',quietly=TRUE))data.table::setDTthreads(1L)
 SCRIPT_VERSION<<-V10_VERSION;RUN_MODE<<-v10_menu();ROOT<<-find_root();DOWNLOADS<<-dirname(ROOT)
 BASE<<-file.path(ROOT,'29_results_resume_v11');CACHE<<-file.path(BASE,'cache');TASK_DIR<<-file.path(CACHE,'tasks');STATE_DIR<<-file.path(CACHE,'state')
 dir.create(file.path(BASE,'runs'),recursive=TRUE,showWarnings=FALSE)
 OUT<<-tempfile(pattern=paste0('run_',format(Sys.time(),'%Y%m%d_%H%M%S'),'_'),tmpdir=file.path(BASE,'runs'));LOG<<-file.path(OUT,'RUN_LOG.txt')
 registry<-file.path(BASE,'registry');for(p in c(registry,CACHE,TASK_DIR,STATE_DIR,OUT,file.path(OUT,'audit')))dir.create(p,recursive=TRUE,showWarnings=FALSE)
 lock<-file.path(BASE,'RUNNING.lock')
 if(!dir.create(lock,showWarnings=FALSE))stop('Er is een run actief of een oude lock: ',lock,' . Verwijder deze map alleen nadat het vorige R-proces is gestopt.')
 writeLines(c(paste('pid',Sys.getpid()),as.character(Sys.time())),file.path(lock,'owner.txt'))
 on.exit(unlink(lock,recursive=TRUE),add=TRUE)
 STATE_FILE<<-file.path(STATE_DIR,'TASK_STATUS.csv');CURRENT_RUN_TASKS_V8<<-character();ACTIVE_COUNTRY<<-'NLD'
 ALLOW_RAW_FALLBACK<<-TRUE;AUTO_INSTALL_R_PACKAGES<<-TRUE;AUTO_PREPARE_COBREROS_REPO<<-TRUE;V10_BACKEND_READY<<-FALSE
 for(n in c('V9_TIMSS_SOURCE_CACHE','V9_PISA_ABSENT','V9_PISA_ERRORS','V9_PISA_WAVE_ERRORS'))assign(n,new.env(parent=emptyenv()),.GlobalEnv)
 V10_HARMONIZED_RESULTS<<-new.env(parent=emptyenv())
 V10_QUARTILE_BASELINE_RESULTS<<-new.env(parent=emptyenv())
 V9_CALIBRATION<<-NULL;V9_CALIBRATION_ERROR<<-NULL;V9_LEGACY_SES<<-NULL
 files<-v10_sources(ROOT,DOWNLOADS,BASE)
 oldtasks<-file.path(ROOT,'28_results_resume_v10/cache/tasks')
 if(dir.exists(oldtasks))files<-unique(c(files,list.files(oldtasks,pattern='\\.csv$',full.names=TRUE)))
 if(exists('V10_BUILTIN_CSV',inherits=TRUE)&&nzchar(V10_BUILTIN_CSV)) {
  builtin<-file.path(BASE,'imports','NLD_REEDS_GEPRODUCEERD_V10.csv')
  if(!file.exists(builtin)){dir.create(dirname(builtin),recursive=TRUE,showWarnings=FALSE);writeLines(V10_BUILTIN_CSV,builtin,useBytes=TRUE)}
  files<-unique(c(files,builtin))
 }
 logmsg('Resultaatbestanden gevonden: ',length(files))
 candidates<-v10_import(files,registry)
 prior_path<-file.path(registry,'PRODUCED_RESULTS.rds');prior<-if(file.exists(prior_path))tryCatch(readRDS(prior_path),error=function(e)NULL) else data.frame()
 if(is.null(prior))prior<-if(file.exists(paste0(prior_path,'.previous')))readRDS(paste0(prior_path,'.previous')) else data.frame()
 if(nrow(prior)) {
  # Technical existence/integrity check only; no re-interpretation of content.
  paths<-unique(prior$source_file);valid<-vapply(paths,function(p)file.exists(p)&&
   all(prior$source_fingerprint[prior$source_file==p]==v10_fingerprint(p)),logical(1))
  changed<-paths[!valid&file.exists(paths)]
  prior<-prior[prior$source_file%in%paths[valid],,drop=FALSE]
  if(length(changed))prior<-v10_bind(list(prior,v10_import(changed,file.path(registry,'changed_produced'))))
 }
 catalogue<-v10_resolve(v10_bind(list(candidates,prior)))
 available<-unique(c(catalogue$country,getOption('pisa.fast.available_countries',character())))
 # Read IEA archive member names for countries not yet present in the master.
 if(RUN_MODE%in%c(3L,4L)) {
  rawdirs<-unique(c(DOWNLOADS,getOption('pisa.fast.source_dirs',character())))
  nameset<-unlist(lapply(rawdirs[dir.exists(rawdirs)],function(p)list.files(p,full.names=TRUE)))
  for(p in nameset[grepl('\\.zip$',nameset,ignore.case=TRUE)])nameset<-c(nameset,tryCatch(unzip(p,list=TRUE)$Name,error=function(e)character()))
  bn<-toupper(basename(nameset));bn<-bn[grepl('^(ASG|ASA|BSG|BSA)[A-Z]{3}',bn)];available<-unique(c(available,substr(bn,4,6)))
 }
 COUNTRIES<<-v10_choice(RUN_MODE,available,getOption('pisa.fast.countries',NULL));if(!length(COUNTRIES))stop('Geen landen gevonden voor deze keuze; gebruik pisa.fast.available_countries.')
 surveys<-toupper(getOption('pisa.fast.surveys',c('PIRLS','TIMSS','PISA')));if(any(!surveys%in%c('PIRLS','TIMSS','PISA')))stop('Unknown survey')
 years<-list(PIRLS=getOption('pisa.fast.pirls_years',c(2001,2006,2011,2016,2021)),TIMSS=getOption('pisa.fast.timss_years',c(2003,2007,2011,2015,2019,2023)),PISA=getOption('pisa.fast.pisa_years',c(2003,2006,2009,2012,2015,2018,2022,2025)))
 PISA_YEARS<<-years$PISA;PIRLS_YEARS<<-years$PIRLS;TIMSS_YEARS<<-years$TIMSS
 if(any(!years$PIRLS%in%c(2001,2006,2011,2016,2021))||any(!years$TIMSS%in%c(2003,2007,2011,2015,2019,2023))||any(!years$PISA%in%c(2003,2006,2009,2012,2015,2018,2022,2025)))stop('Unsupported wave')
 req<-v10_reuse_existing_constructs(v10_requirements(COUNTRIES,surveys,years),catalogue)
 catalogue<-v10_resolve(v10_bind(list(catalogue,v10_aggregate_derivatives(catalogue,req))))
 idx<-match(req$metric_key,catalogue$metric_key);req$availability<-ifelse(is.na(idx),'MISSING',catalogue$availability[idx]);req$source_file<-ifelse(is.na(idx),'',catalogue$source_file[idx])
 v10_write(req,file.path(OUT,'SLIDE_REQUIREMENTS_BEFORE.csv'));v10_write(catalogue,file.path(registry,'RESULTS_REGISTER.csv'))
 logmsg('Landen: ',paste(COUNTRIES,collapse=','),'; targets: ',nrow(req),'; bestaand bruikbaar: ',sum(req$availability=='AVAILABLE_POINT'))
 missing<-req[req$availability=='MISSING',,drop=FALSE];holds<-list();actions<-list();newrows<-list()
 conflict_targets<-req[req$availability=='CONFLICT',,drop=FALSE]
 if(nrow(conflict_targets)){conflict_targets$reason<-'Conflicting existing source values require source review; no automatic recalculation';holds[[1L]]<-conflict_targets}
 # Persist HOLDs by exact target and input stamp. An unchanged restart does not
 # repeat failed imports or unresolved mappings. retry_holds=TRUE explicitly retries.
 hpath<-file.path(registry,'HOLDS.csv');oldholds<-v10_read(hpath)
 backendstamp<-paste(V10_VERSION,getOption('pisa.fast.mapping_version','1'),sep='|')
 srcdirs<-unique(c(DOWNLOADS,getOption('pisa.fast.source_dirs',character())))
 inputfiles<-unique(unlist(lapply(srcdirs[dir.exists(srcdirs)],function(d)list.files(d,pattern='\\.(zip|sav|sas7bdat)$',full.names=TRUE,ignore.case=TRUE))))
 mapfile<-getOption('pisa.fast.codebook_map',file.path(ROOT,'CODEBOOK_MAP.csv'))
 inputfiles<-unique(c(inputfiles,mapfile[file.exists(mapfile)]))
 inputstamp<-paste(c(backendstamp,vapply(inputfiles,v10_fingerprint,character(1))),collapse=';')
 enginepaths<-c(getOption('pisa.slide.engine',''),file.path(DOWNLOADS,c('PISA_PIRLS_LAATSTE_R_RUN_20260927_RESUME_GENDER_HASH_FIX.R','PISA_PIRLS_LAATSTE_R_RUN_20260927_WINDOWS_FIX.R')))
 inputstamp<-paste(inputstamp,paste(vapply(enginepaths[file.exists(enginepaths)],v10_fingerprint,character(1)),collapse=';'),sep='|')
 chunks<-if(isTRUE(getOption('pisa.fast.inventory_only',FALSE)))list() else split(seq_len(nrow(missing)),paste(missing$country,missing$survey,missing$year,sep='|'))
 for(ids in chunks) {
  wave<-missing[ids,,drop=FALSE];ACTIVE_COUNTRY<<-wave$country[1];s<-wave$survey[1];y<-wave$year[1];obj<-NULL;obj_error<-NULL
  V11_REQUIRED_MAPPINGS<<-any(grepl('language|migration',wave$module))
  modules<-split(seq_len(nrow(wave)),paste(wave$module,wave$domain,wave$definition,wave$peer_definition,sep='|'))
  for(ii in modules) {
   q<-wave[ii,,drop=FALSE]
   if(nrow(oldholds)&&!isTRUE(getOption('pisa.fast.retry_holds',FALSE))) {
    k<-match(q$metric_key,oldholds$metric_key);skip<-!is.na(k)&oldholds$input_stamp[k]==inputstamp
    if(any(skip)){holds[[length(holds)+1L]]<-oldholds[k[skip],,drop=FALSE];q<-q[!skip,,drop=FALSE]}
   }
   if(!nrow(q))next
   logmsg('Ontbrekend: ',ACTIVE_COUNTRY,' ',s,' ',y,' ',q$module[1],' ',q$domain[1])
   # Stable task filename uses an MD5 of the complete logical target set.
   tf<-tempfile();writeLines(sort(q$metric_key),tf);taskkey<-unname(tools::md5sum(tf));unlink(tf)
   resultpath<-file.path(TASK_DIR,paste0(taskkey,'.csv'))
   z<-tryCatch({
    saved<-if(file.exists(resultpath))v10_read(resultpath) else data.frame()
    if(nrow(saved)&&all(q$metric_key%in%saved$metric_key)&&all(saved$contract==V10_CONTRACT)&&'input_stamp'%in%names(saved)&&all(saved$input_stamp==inputstamp)) {
     saved[match(q$metric_key,saved$metric_key),,drop=FALSE]
    } else {
    v10_init_backend()
    if(s=='PISA'&&q$module[1]=='peer_baseline'&&q$definition[1]=='Cobreros_fourwave_13item_trend_comparable') {
     b<-v10_once(V10_QUARTILE_BASELINE_RESULTS,paste(ACTIVE_COUNTRY,y,sep='|'),function() {
      g<-v9_harmonized_country(ACTIVE_COUNTRY,y);baseq<-q[rep(1L,2L),,drop=FALSE];baseq$stat<-c('q1_share','q4_share')
      v10_cobreros_quartile_baseline(g,baseq)
     })
     for(n in c('estimate','se','ci_low','ci_high'))q[[n]]<-b[[n]][match(q$stat,b$stat)]
     q
    } else if(q$module[1]=='ses_harmonized'||s=='PISA'&&q$module[1]=='ses_peer_exposure') {
     # One wave calculation serves every domain and both peer units. No repeated
     # PV/replicate passes when this country-year has several missing modules.
     raw<-v10_once(V10_HARMONIZED_RESULTS,paste(ACTIVE_COUNTRY,y,sep='|'),function() {
      g<-v9_harmonized_country(ACTIVE_COUNTRY,y);a<-pisa_harmonized_outputs(g)
      raw<-v9_master_rows(v9_decorate(list(results=v10_bind(list(a$ses,a$peers)),holds=a$holds),ACTIVE_COUNTRY,'harmonized_ses')$results)
      v10_adapt(raw,resultpath,V10_VERSION,20L)
     })
     k<-match(q$metric_key,raw$metric_key);if(anyNA(k))stop('Gevraagde harmonized targets ontbreken in backend-output.')
     raw[k,,drop=FALSE]
    } else {
     if(!is.null(obj_error))stop(obj_error)
     if(is.null(obj)) {
      obj<-tryCatch(switch(s,PIRLS=load_pirls_minimal(y,TRUE),TIMSS=load_timss_minimal(y,TRUE),PISA=load_pisa_minimal(y)),error=function(e){obj_error<<-conditionMessage(e);NULL})
      if(is.null(obj))stop(obj_error)
      obj<-v11_apply_demographics(obj)
     }
     # Codebook-specific replacement can restore the zero-coverage mapper and
     # parent birthplace columns. It must leave weights/IDs/PVs aligned.
     hook<-getOption('pisa.fast.canonical_mapper',NULL)
     if(is.function(hook)&&!isTRUE(obj$meta$v11_user_mapped)){changed<-hook(obj);if(nrow(changed$data)!=nrow(obj$data)||!identical(changed$data$STUDENT_ID,obj$data$STUDENT_ID))stop('Mapper changed pupil alignment');obj<-changed;obj$meta$v11_user_mapped<-TRUE}
     v10_compute(obj,q)
    }
    }
   },error=function(e)e)
   if(inherits(z,'error')) {
    q$reason<-conditionMessage(z);q$input_stamp<-inputstamp;q$updated<-as.character(Sys.time());holds[[length(holds)+1L]]<-q
    actions[[length(actions)+1L]]<-data.frame(country=ACTIVE_COUNTRY,survey=s,year=y,module=q$module[1],action='HELD',result_file='',message=conditionMessage(z))
   } else {
    good<-is.finite(z$estimate)&is.finite(z$se)&z$se>=0
    if(any(!good)){h<-q[!good,,drop=FALSE];h$reason<-'Non-finite estimate or design SE';h$input_stamp<-inputstamp;h$updated<-as.character(Sys.time());holds[[length(holds)+1L]]<-h}
    z<-z[good,,drop=FALSE]
    if(nrow(z)) {
     z$contract<-V10_CONTRACT;z$metric_key<-v10_key(z);z$source_file<-resultpath;z$source_script<-V10_VERSION;z$source_row<-seq_len(nrow(z));z$priority<-20L
     z$status<-'conditional';z$availability<-'AVAILABLE_POINT';z$uncertainty_status<-'SE_AVAILABLE';z$source_fingerprint<-''
     z$producer_code_id<-if(exists('V10_CODE_ID',inherits=TRUE))V10_CODE_ID else V10_VERSION
     z$producer_run<-OUT;z$input_stamp<-inputstamp
     z$method_note<-'PV/design replicate weights; missing peer status excluded; PISA direct unit is school x programme; conditional until substantive validation'
     v10_write(z,resultpath);z$source_fingerprint<-v10_fingerprint(resultpath)
     newrows[[length(newrows)+1L]]<-z;prior<-v10_bind(list(prior,z));v10_save_rds(prior,prior_path)
     actions[[length(actions)+1L]]<-data.frame(country=ACTIVE_COUNTRY,survey=s,year=y,module=q$module[1],action='PRODUCED',result_file=resultpath,message='Only targets missing from register exported')
    }
   }
   v10_write(v10_bind(holds),hpath);v10_write(v10_bind(actions),file.path(OUT,'RUN_ACTIONS.csv'))
  }
  rm(obj);
  for(e in list(V10_HARMONIZED_RESULTS,V10_QUARTILE_BASELINE_RESULTS))rm(list=ls(e),envir=e)
  gc(FALSE)
 }
 catalogue<-v10_resolve(v10_bind(list(candidates,prior)))
 catalogue<-v10_resolve(v10_bind(list(catalogue,v10_aggregate_derivatives(catalogue,req))));v10_write(catalogue,file.path(registry,'RESULTS_REGISTER.csv'))
 idx<-match(req$metric_key,catalogue$metric_key);req$availability<-ifelse(is.na(idx),'MISSING',catalogue$availability[idx]);req$source_file<-ifelse(is.na(idx),'',catalogue$source_file[idx])
 v10_write(req,file.path(OUT,'SLIDE_REQUIREMENTS_AFTER.csv'))
 open<-v11_open_targets(req,v10_bind(holds));v10_write(open,file.path(OUT,'OPEN_TARGETS.csv'))
 v10_write(v11_grid_status(req,v10_bind(holds)),file.path(OUT,'RESULT_GRID.csv'))
 selected<-catalogue[catalogue$country%in%COUNTRIES&catalogue$availability=='AVAILABLE_POINT',,drop=FALSE]
 v10_write(selected,file.path(OUT,'RESULTS_FOR_SLIDES.csv'));v10_write(selected,file.path(OUT,'RESULTS_FOR_DASHBOARD.csv'))
 # Comparator uses the complete register, including countries produced in older
 # runs and countries outside today's selected scope. No new reference microdata.
 ref<-v11_reference(catalogue,req,registry);v10_write(ref$results,file.path(OUT,'REFERENCE_FIXED_PANELS.csv'))
 v10_write(ref$panels,file.path(OUT,'REFERENCE_PANEL_REGISTER.csv'))
 v10_write(ref$members,file.path(OUT,'REFERENCE_MEMBERS.csv'));v10_write(ref$holds,file.path(OUT,'REFERENCE_MISSING.csv'))
 routes<-req;routes$dashboard_panel<-paste(routes$module,routes$domain,sep=':');routes$country_profile<-routes$country
 routes$migration_switch<-ifelse(grepl('parents|parent',routes$definition),routes$definition,'')
 routes$display_rule<-'Use exact key only; percent/proportion distinct; unavailable=gap; conditional status retained'
 routes$render_role<-'PRIMARY'
 extra<-selected[!selected$metric_key%in%routes$metric_key,,drop=FALSE]
 if(nrow(extra)) {
  extra$slides<-ifelse(extra$module=='migration_generation','14;15',ifelse(extra$module=='migration_peer_exposure','19',ifelse(extra$module=='high_proficiency_peer_exposure','20','supplement')))
  extra$dashboard_panel<-paste(extra$module,extra$domain,sep=':');extra$country_profile<-extra$country
  extra$migration_switch<-ifelse(grepl('parents|parent',extra$definition),extra$definition,'')
  extra$display_rule<-'Existing supplement; preserve definition, sample policy and source variant; do not average into primary results'
  extra$render_role<-'SUPPLEMENT';routes<-v10_bind(list(routes,extra))
 }
 v10_write(routes,file.path(OUT,'DASHBOARD_ROUTING.csv'))
 datasets<-lapply(split(seq_len(nrow(catalogue)),catalogue$source_file),function(ix) {
  z<-catalogue[ix,,drop=FALSE]
  data.frame(result_file=z$source_file[1],source_scripts=paste(unique(z$source_script),collapse=';'),
   countries=paste(sort(unique(z$country)),collapse=';'),surveys=paste(sort(unique(z$survey)),collapse=';'),
   years=paste(sort(unique(z$year)),collapse=';'),registered_cells=nrow(z),
   current_dashboard_export=file.path(OUT,'RESULTS_FOR_DASHBOARD.csv'),
   routing_file=file.path(OUT,'DASHBOARD_ROUTING.csv'),fingerprint=v10_fingerprint(z$source_file[1]))
 })
 v10_write(v10_bind(datasets),file.path(registry,'DATASETS_REGISTER.csv'))
 scriptpath<-getOption('pisa.fast.script',file.path(DOWNLOADS,'PISA_RESULTATEN_RESUME_V11_20261001.R'))
 v10_write(data.frame(script_version=V10_VERSION,contract=V10_CONTRACT,script_path=scriptpath,
  code_id=if(exists('V10_CODE_ID',inherits=TRUE))V10_CODE_ID else V10_VERSION,
  local_md5=if(file.exists(scriptpath))unname(tools::md5sum(scriptpath)) else '',
  engine_path=if(isTRUE(V10_BACKEND_READY))ENGINE else 'Not needed for this run',
  source_inventory=file.path(registry,'SOURCE_INVENTORY.csv')),file.path(registry,'SCRIPTS_REGISTER.csv'))
 v10_write(catalogue[catalogue$availability=='CONFLICT',,drop=FALSE],file.path(OUT,'CONFLICTS_REVIEW.csv'))
 writeLines(c('Original sources are read-only. No original rows deleted.',
  'Unrecognised constructs remain in their source files and SOURCE_INVENTORY; not silently substituted.',
  'Registry conflicts are retained. Conditional estimates are not a scientific release.',
  'No dashboard UI or PowerPoint file edited by this script.'),file.path(OUT,'LOSS_REGISTER.txt'))
 summary<-c(paste('Version:',V10_VERSION),paste('Countries:',paste(COUNTRIES,collapse=',')),
  paste('Required cells:',nrow(req)),paste('Available point estimates:',sum(req$availability=='AVAILABLE_POINT')),
  paste('Open cells:',sum(req$availability!='AVAILABLE_POINT')),paste('New results:',nrow(v10_bind(newrows))),
  paste('Reference cells:',nrow(ref$results)),paste('Reference cells incomplete:',nrow(ref$holds)),paste('Output:',OUT))
 writeLines(summary,file.path(OUT,'RUN_SUMMARY.txt'));cat(paste(summary,collapse='\n'),'\n')
 invisible(OUT)
}

# Function-only mode supports tests and another pipeline without starting work.
# The build appends the legacy backend function definitions and the entry point.

# Frozen classifications: OECD membership 2026-10-01; World Bank FY2027.
V11_HIC34 <- c('AUS','AUT','BEL','CAN','CHL','CRI','CZE','DNK','EST','FIN','FRA','DEU','GRC','HUN','ISL','IRL','ISR','ITA','JPN','KOR','LVA','LTU','LUX','NZL','NOR','POL','PRT','SVK','SVN','ESP','SWE','CHE','GBR','USA')
V11_OECD37 <- c(V11_HIC34,'COL','MEX','TUR')
V11_GROUPS <- list(OECD_HIGH_INCOME=V11_HIC34,OECD_ALL=V11_OECD37)

v11_hash <- function(x) {
 f<-tempfile();on.exit(unlink(f));writeLines(x,f,useBytes=TRUE);unname(tools::md5sum(f))
}
v11_panel_key <- function(z) {
 # Groups and statistics in the same construct/unit use one common panel.
 do.call(paste,c(lapply(c('survey','domain','module','definition','peer_definition','threshold','unit','calculation_policy'),function(n)v10_text(z[[n]])),sep='|'))
}
v11_reference <- function(z,requirements,registry) {
 empty<-list(results=data.frame(),members=data.frame(),holds=data.frame(),panels=data.frame())
 if(!nrow(z)||!nrow(requirements))return(empty)
 groups<-getOption('pisa.fast.reference_groups',V11_GROUPS)
 if(!is.list(groups)||is.null(names(groups))||any(!nzchar(names(groups))))stop('Reference groups require unique names and ISO3 lists')
 if(anyDuplicated(names(groups)))stop('Duplicate group names')
 minimum<-getOption('pisa.fast.reference_min_countries',3L)
 if(length(minimum)!=1||!is.finite(minimum)||minimum<2)stop('reference_min_countries must be >= 2')
 path<-file.path(registry,'FIXED_PANELS.rds')
 old<-if(file.exists(path))readRDS(path) else list()
 out<-members<-holds<-panels<-list()
 t<-requirements;t$series<-v10_key(t,FALSE);t<-t[!duplicated(t$series),,drop=FALSE]
 t$panel_family<-v11_panel_key(t);z$series<-v10_key(z,FALSE)
 for(gn in names(groups)) {
  pool<-sort(setdiff(v10_codes(groups[[gn]]),'NLD'))
  if(any(!grepl('^[A-Z]{3}$',pool)))stop('Invalid reference country code')
  for(ix in split(seq_len(nrow(t)),t$panel_family)) {
   tt<-t[ix,,drop=FALSE];expected<-sort(unique(tt$series));family<-tt$panel_family[1]
   id<-paste0(gn,'_',substr(v11_hash(c(gn,pool,family,expected)),1,16))
   good<-z[z$country%in%pool&z$series%in%expected&z$availability=='AVAILABLE_POINT'&is.finite(z$estimate),,drop=FALSE]
   eligible<-pool[vapply(pool,function(cc){a<-good[good$country==cc,,drop=FALSE];!anyDuplicated(a$series)&&setequal(a$series,expected)},logical(1))]
   frozen<-old[[id]]
   if(is.null(frozen)||isTRUE(getOption('pisa.fast.rebuild_panels',FALSE))) {
    frozen<-list(countries=eligible,frozen_at=as.character(Sys.time()),id=id)
    # Incomplete small panels are proposals only and are not frozen.
    if(length(eligible)>=minimum)old[[id]]<-frozen
   }
   use<-frozen$countries
   complete<-length(use)>=minimum&&all(use%in%eligible)
   panel<-data.frame(panel_id=id,reference_group=gn,panel_family=family,
     years=paste(sort(unique(tt$year)),collapse=';'),target_members=paste(pool,collapse=';'),
     members=paste(use,collapse=';'),excluded=paste(setdiff(pool,use),collapse=';'),
     n=length(use),status=if(complete)'FROZEN_COMPLETE' else 'HELD_INCOMPLETE',frozen_at=frozen$frozen_at,
     rule='Equal countries; NL excluded; identical membership across all required years/groups/statistics within this panel family')
   panels[[length(panels)+1L]]<-panel
   if(!complete) {
    h<-tt;h$panel_id<-id;h$reference_group<-gn;h$reason<-if(length(use)<minimum)'Too few complete countries; no average emitted' else 'Previously frozen member now missing; panel not silently changed'
    h$missing_countries<-paste(setdiff(use,eligible),collapse=';');holds[[length(holds)+1L]]<-h;next
   }
   for(j in seq_len(nrow(tt))) {
    r<-tt[j,,drop=FALSE];q<-good[good$country%in%use&good$series==r$series,,drop=FALSE]
    stopifnot(nrow(q)==length(use),!anyDuplicated(q$country))
    r$country<-paste0('REF_',gn);r$estimate<-mean(q$estimate)
    r$se<-r$ci_low<-r$ci_high<-NA_real_;r$comparator_n<-length(use)
    r$panel_id<-id;r$reference_group<-gn;r$membership_status<-'FROZEN_COMPLETE'
    r$method<-'Arithmetic mean of country statistics, not a pooled-student statistic; NL excluded'
    r$uncertainty_method<-'Point estimate only by project specification'
    out[[length(out)+1L]]<-r
    q$panel_id<-id;q$reference_group<-gn;q$weight_in_reference<-1/length(use)
    members[[length(members)+1L]]<-q
   }
  }
 }
 v10_save_rds(old,path)
 list(results=v10_bind(out),members=v10_bind(members),holds=v10_bind(holds),panels=v10_bind(panels))
}

v11_grid_status <- function(req,holds) {
 req$grid_status<-ifelse(req$availability=='AVAILABLE_POINT','REUSED_OR_PRODUCED',ifelse(req$availability=='CONFLICT','CONFLICT','MISSING_COMPUTABLE'))
 req$reason<-''
 if(nrow(holds)) {
  k<-match(req$metric_key,holds$metric_key);ok<-!is.na(k);req$reason[ok]<-holds$reason[k[ok]]
  open<-req$availability!='AVAILABLE_POINT'&req$availability!='CONFLICT';r<-tolower(req$reason)
  req$grid_status[open&nzchar(r)]<-'BLOCKED_COMPUTATION'
  req$grid_status[open&grepl('mapper|mapping|construct|categorie|geboorte|taal|migration|canonical gender',r)]<-'BLOCKED_MAPPING'
  req$grid_status[open&grepl('bron|source|bestand|file|engine|absent',r)]<-'SOURCE_MISSING_OR_UNRESOLVED'
  req$grid_status[open&grepl('locked 34|calibration',r)]<-'OUTSIDE_CALIBRATION'
 }
 req
}
v11_open_targets <- function(req,holds) {x<-v11_grid_status(req,holds);x[x$availability!='AVAILABLE_POINT',,drop=FALSE]}

v10_language <- function(obj,frequency=FALSE) {
 g<-tolower(v10_text(obj$data$DEMO_LANGUAGE));g[g=='almost']<-'almost_always'
 if(length(g)!=nrow(obj$data))stop('BLOCKED_MAPPING: Geen thuistaalconstructie.')
 if(frequency) {
  g[!g%in%c('always','almost_always','always_or_almost_always','sometimes','never')]<-NA_character_
  if(!any(!is.na(g)))stop('BLOCKED_MAPPING: Geen gecontroleerde taal-frequentiecategorieen.')
  return(g)
 }
 L<-language_groups(obj);if(!isTRUE(L$ok))stop(L$reason);L$group
}

# Conservative label-based mappings: no numeric code is guessed. Optional
# CODEBOOK_MAP.csv supplies explicit reviewed codes if English value labels
# are absent. Columns survey,year,variable,target,code,value,source.
# targets mother_here/father_here/language; values TRUE/FALSE or canonical
# language categories. All unknown codes remain NA.
v11_labels <- function(x) {
 labs<-attr(x,'labels');if(is.null(labs))labs<-attr(x,'value.labels')
 if(is.factor(x)||is.character(x))return(tolower(trimws(as.character(x))))
 if(is.null(labs)||is.null(names(labs)))return(rep(NA_character_,length(x)))
 tolower(trimws(names(labs)[match(as.character(x),as.character(labs))]))
}
v11_map_raw <- function(obj,raw) {
 if(!is.data.frame(raw)||nrow(raw)!=nrow(obj$data))return(obj)
 s<-toupper(obj$meta$survey);y<-as.integer(obj$meta$year);d<-obj$data
 cfg<-getOption('pisa.fast.codebook_map',file.path(ROOT,'CODEBOOK_MAP.csv'))
 maps<-if(is.character(cfg)&&length(cfg)==1&&file.exists(cfg))v10_read(cfg) else data.frame()
 if(nrow(maps)) {
  need<-c('survey','year','variable','target','code','value','source')
  if(!all(need%in%names(maps)))stop('CODEBOOK_MAP mist kolommen: ',paste(setdiff(need,names(maps)),collapse=','))
  maps<-maps[toupper(maps$survey)==s&maps$year==y,,drop=FALSE]
  if(any(!nzchar(v10_text(maps$source))))stop('CODEBOOK_MAP vereist gecontroleerde bron per regel')
 }
 for(target in c('mother_here','father_here','language')) {
  dest<-switch(target,mother_here='MOTHER_BORN_HERE',father_here='FATHER_BORN_HERE',language='DEMO_LANGUAGE')
  mm<-if(nrow(maps))maps[maps$target==target,,drop=FALSE] else data.frame()
  value<-NULL;variable<-NULL;method<-NULL
  if(nrow(mm)) {
   vars<-unique(mm$variable);if(length(vars)!=1)stop('Meerdere codebookvariabelen voor dezelfde target/wave')
   if(vars%in%names(raw)) {
    if(anyDuplicated(as.character(mm$code)))stop('Dubbele codebookcodes')
    value<-mm$value[match(as.character(raw[[vars]]),as.character(mm$code))]
    if(target!='language') {if(any(!is.na(value)&!value%in%c('TRUE','FALSE')))stop('Ouderwaarde moet TRUE/FALSE zijn');value<-ifelse(is.na(value),NA,value=='TRUE')}
    variable<-vars;method<-paste('Reviewed codebook:',paste(unique(mm$source),collapse=';'))
   }
  } else {
   # Candidates need a matching question label, plus unambiguous value labels.
   vars<-names(raw)[vapply(names(raw),function(n){
    lab<-tolower(paste(attr(raw[[n]],'label'),collapse=' '))
    if(target=='mother_here')grepl('mother',lab)&&grepl('born|birth',lab)
    else if(target=='father_here')grepl('father',lab)&&grepl('born|birth',lab)
    else grepl('language',lab)&&grepl('home',lab)
   },logical(1))]
   vv<-list()
   for(n in vars) {
    l<-v11_labels(raw[[n]]);v<-rep(NA_character_,length(l))
    if(target!='language') {
     yes<-!is.na(l)&grepl('^(in )?(the )?(country of (test|assessment)|country of birth is country of test|test country|this country)$',l)
     no<-!is.na(l)&grepl('^(in )?(an? )?(other|another) country$|^abroad$',l)
     v<-rep(NA,length(l));v[yes]<-TRUE;v[no]<-FALSE
    } else {
     v[l%in%c('always')]<-'always';v[l%in%c('almost always')]<-'almost_always'
     v[l%in%c('always or almost always','always/almost always')]<-'always_or_almost_always'
     v[l%in%c('sometimes')]<-'sometimes';v[l%in%c('never')]<-'never'
     if(s=='PISA') {
      v[l%in%c('language of the test','language of test','test language','language of assessment')]<-'test_language_home'
      v[l%in%c('another language','other language')]<-'other_language_home'
     }
    }
    if(any(!is.na(v)))vv[[n]]<-v
   }
   if(length(vv)==1){variable<-names(vv);value<-vv[[1]];method<-'Unambiguous source question and value labels'}
  }
  if(!is.null(value)) {
   d[[dest]]<-value
   if(exists('OUT',inherits=TRUE)&&dir.exists(OUT)) {
    audit<-data.frame(survey=s,year=y,country=if(exists('ACTIVE_COUNTRY'))ACTIVE_COUNTRY else '',target=target,variable=variable,method=method,n=nrow(d),classified=sum(!is.na(value)))
    ap<-file.path(OUT,'audit','DEMOGRAPHIC_MAPPINGS.csv');v10_write(v10_bind(list(v10_read(ap),audit)),ap)
   }
  }
 }
 obj$data<-d;obj$meta$v11_demographic_labels_checked<-TRUE
 obj$meta$v11_mapping_stamp<-v11_mapping_stamp();obj
}
v11_apply_demographics <- function(obj) {
 # Also accepts canonical objects which retained the labelled source columns.
 v11_map_raw(obj,obj$data)
}
v11_install_raw_mapper <- function() {
 if(exists('rc2_add_demographics',envir=.GlobalEnv)) {
  original<-get('rc2_add_demographics',envir=.GlobalEnv)
  wrapper<-local({fun<-original;function(obj,raw,...)v11_map_raw(fun(obj,raw,...),raw)})
  assign('rc2_add_demographics',wrapper,envir=.GlobalEnv)
 }
}

# Invalidate only demographic-incomplete canonical caches when a missing
# demographic result actually requires raw fields. Original caches are retained.
v11_install_cache_guard <- function() {
 original<-get('canonical_ok',envir=.GlobalEnv)
 wrapper<-local({fun<-original;function(x,survey,year,need){
  if(!isTRUE(fun(x,survey,year,need)))return(FALSE)
  required<-get0('V11_REQUIRED_MAPPINGS',envir=.GlobalEnv,ifnotfound=FALSE)
  if(isTRUE(required)&&(!isTRUE(x$meta$v11_demographic_labels_checked)||!identical(x$meta$v11_mapping_stamp,v11_mapping_stamp())))return(FALSE)
  TRUE
 }})
 assign('canonical_ok',wrapper,envir=.GlobalEnv)
}

v11_mapping_stamp <- function() {
 p<-getOption('pisa.fast.codebook_map',file.path(ROOT,'CODEBOOK_MAP.csv'))
 paste('V11_labels_1',getOption('pisa.fast.mapping_version','1'),v10_fingerprint(p),sep='|')
}

